window.EXERCISE_DATA = [{"id":"static-neck-flexion-extension","name":"Static Neck Flexion and Extension","eq":"bodyweight","p":["traps"],"s":[],"ins":["An exercise to either build or warm-up front and back neck muscles.","Stand or sit with your head in neutral position.","Place both of your hands on your forehead.","Press your head against your hands and contract your neck muscles.","Keep your head from moving forward. Hold for at least 30 seconds.","Repeat with hands on the back of your head, pressing against them."],"img":["0001-relaxation.svg","0001-tension.svg"]},{"id":"static-neck-side-flexion","name":"Static Neck Side Flexion","eq":"bodyweight","p":["traps"],"s":[],"ins":["Stand or sit with your head in neutral position.","Place your left hand against the left side of your head, above your ear.","Push your head against your hand, without moving your head.","Repeat with your right hand, right side of your head."],"img":["0002-relaxation.svg","0002-tension.svg"]},{"id":"seated-military-press","name":"Seated Military Press","eq":"barbell","p":["shoulders"],"s":["triceps"],"ins":["Sit on the bench with your toes pointing straight out, back straight and abs drawn in.","Grip the bar with your palms facing outwards and your hands shoulder width apart","With bar in front of your head, press\u00a0upwards extending your arms but not locking them.","Pause at the top and then in a controlled movement lower the bar to the starting position."],"img":["0004-relaxation.svg","0004-tension.svg"]},{"id":"shoulder-shrugs","name":"Dumbbell Shoulder Shrugs","eq":"dumbbell","p":["traps"],"s":[],"ins":["Stand with your feet shoulder width apart and a slight bend in your knees.","Hold a dumbbell in each hand and with your arms at your sides.","Lower your shoulders as much as possible.","With your arms straight raise both shoulders up towards your ears.","Hold the upright positions for a moment and then lower in a controlled motion."],"img":["0005-relaxation.svg","0005-tension.svg"]},{"id":"front-cable-raises","name":"Front Cable Raises","eq":"cable","p":["shoulders"],"s":["chest","forearms"],"ins":["Place the pulley on the setting just above the floor.","Stand with your feet shoulder width apart, your abs drawn in and your knees slightly bent.","Starting at waist height, take the pulley in your left hand, palm facing the floor with otherwise known as an overhand grip, and raise your straight arm up towards your left shoulder.","At shoulder height pause for a moment.","With a controlled movement resist the weight and slowly lower your arm back to starting position at your waist.","Repeat the exercise with your right arm."],"img":["0008-relaxation.svg","0008-tension.svg"]},{"id":"cable-shoulder-shrugs","name":"Cable Shoulder Shrugs","eq":"cable","p":["traps"],"s":["shoulders"],"ins":["Attach a pulley to the lowest setting on cable machine.","Stand with your feet shoulder width apart, your abs drawn and your back straight.","Start with the pulley at waist height.","Grasp the pulley and shrug your shoulders up while keeping your arms extended.","Hold this position for a moment then with a controlled motion return to the starting position of the pulley to waist height."],"img":["0009-relaxation.svg","0009-tension.svg"]},{"id":"smith-machine-upright-row","name":"Smith Machine Upright Row","eq":"smith machine","p":["shoulders"],"s":["biceps","upper back"],"ins":["Stand with your feet shoulder width apart and your abs drawn in.","Place the bar on the Smith Machine in the position where your arms are fully extended in front of you.","Place your hands shoulder width apart and raise the bar up towards your chin with a controlled motion.","Pause at the top for a moment and rotate your shoulder blades together.","Lower the bar to the starting position."],"img":["0013-relaxation.svg","0013-tension.svg"]},{"id":"upright-barbell-rows","name":"Upright Barbell Rows","eq":"barbell","p":["shoulders"],"s":["biceps","upper back"],"ins":["Stand with your feet shoulder width apart, your abs drawn in and back straight.","Place the bar on rack in the position where your arms are fully extended in front of you with your elbows slightly bent.","Place your hands shoulder width apart and raise the bar up towards your chin with a controlled motion.","Pause at the top for a moment and rotate your shoulder blades together.","Lower the bar to the starting position.","Repeat"],"img":["0014-relaxation.svg","0014-tension.svg"]},{"id":"upright-cable-row","name":"Upright Cable Row","eq":"cable","p":["shoulders"],"s":["upper back","biceps"],"ins":["Attach a straight bar to the pulley on the floor.","Stand with your feet shoulder width apart, your abs drawn in and your back straight.","Grasp the bar with an overhand grasp (your palms facing downwards) and pull it up towards your waist, this is the starting position.","Raise the bar up to in line with your shoulders.","Pause at the top and rotate your shoulder blades together.","Lower the bar in a controlled motion to the starting position."],"img":["0015-relaxation.svg","0015-tension.svg"]},{"id":"dumbbell-upright-rows","name":"Dumbbell Upright Row","eq":"dumbbell","p":["shoulders"],"s":["biceps","upper back"],"ins":["Grasp a dumbbell in each hand with an overhand grip (palms facing downwards) and hold them in front of your thighs.","Stand with your feet shoulder width apart, your abs drawn in and your back straight.","Starting with the dumbbells at your thighs, slowly raise them up towards your shoulders by bending your elbows.","Pause at the top and rotate your shoulder blades together.","Lower the dumbbells in a controlled motion to your thighs.","Repeat"],"img":["0016-relaxation.svg","0016-tension.svg"]},{"id":"bent-over-lateral-cable-raises","name":"Bent-over Lateral Cable Raises","eq":"cable","p":["shoulders"],"s":["traps","lats"],"ins":["Grasp the handle of the low pulley with your right hand.","Bend forward from the waist; your upper body should be nearly parallel with the floor. Bend your knees slightly and place your left hand on your left thigh. Let your right arm hang from your shoulder in front of you with your elbow slightly bent. This is your starting position.","Lift your right arm, keeping your elbow slightly bent.","Keep moving your arm until it is parallel to the floor, in line with your right ear.","Slowly bring the weight back down to the starting position.","Perform exercise on left arm and then repeat."],"img":["0017-relaxation.svg","0017-tension.svg"]},{"id":"lateral-dumbbell-raises","name":"Dumbbell Lateral Raise","eq":"dumbbell","p":["shoulders"],"s":["forearms"],"ins":["Grasp a dumbbell in each hand, palms facing inward towards your body and the dumbbells at your sides.","Standing with your feet shoulder with apart, draw your abs in and bend your knees slightly.","While keeping your torso still, raise the your arms up to the sides keeping your arms straight with a slight bend in the elbows.","Raise your arms up until in line with your shoulders, your palms should face the floor.","Hold the position for a moment then in a controlled movement lower your arms to the starting position.","Repeat"],"img":["0018-relaxation.svg","0018-tension.svg"]},{"id":"ball-wall-circles","name":"Ball Wall Circles","eq":"ball","p":["shoulders"],"s":["biceps","triceps"],"ins":["Stand upright with your feet shoulder width apart.","Place a Swiss ball at chest height against a wall and with your left hand, roll the ball in small circles against the wall.","Keep your arm fully extended with a slight bend in the elbow.","Reverse the direction of the circles.","Switch arms."],"img":["0019-relaxation.svg","0019-tension.svg"]},{"id":"back-flys-exercise-band","name":"Back Flys with Exercise Band","eq":"band","p":["shoulders"],"s":["triceps","lats"],"ins":["Place an exercise band around a post or machine at mid chest height.","Stand with your feet shoulder width apart, abs drawn in and knees slightly bent.","Stand back from the post so there is tension in the band, grasping the band with your arms extended in front of you and a slight bend in your elbows; this is your starting position.","Bring your arms back in a controlled motion till they are parallel at your sides and in line with your shoulders.","Slowly return your arms to the starting position in front of your chest.","Repeat."],"img":["0020-relaxation.svg","0020-tension.svg"]},{"id":"flat-bench-leg-raises","name":"Flat Bench Leg Raises","eq":"bodyweight","p":["abs"],"s":[],"ins":["Lie on a flat bench with your hands under your hips supporting your back.","Your legs should be unsupported by the bench from below your knees.","With your feet together and your toes flexed upwards, raise your straight legs up a few cm off the bench; both of your legs should have no contact with the bench. This is your starting position.","Keep your legs straight with a slight bend in the knees and raise your legs to just before 90 degrees with your hips.","Pause at the top and lower your legs in slow controlled manner back to the starting position.","Repeat."],"img":["0021-relaxation.svg","0021-tension.svg"]},{"id":"smith-machine-rear-deltoid-row","name":"Smith Machine Rear Deltoid Row","eq":"smith machine","p":["shoulders"],"s":["upper back","biceps"],"ins":["Set the bar to the lowest setting.","Place your feet shoulder width apart with a slight bend in the knees.","Bend at the waist while keeping your back straight and chest parallel to the floor.","Grasp the bar slightly wider than your shoulders with an overhand grasp and your arms straight with a slight bend in the elbows.","Raise the bar with a controlled motion to the lower part of your chest by bending and elevating your elbows.","Hold for a moment and then lower to the starting position.","Repeat."],"img":["0022-relaxation.svg","0022-tension.svg"]},{"id":"lying-rear-lateral-raise","name":"Lying Rear Lateral Raise","eq":"dumbbell","p":["shoulders"],"s":[],"ins":["Place the dumbbells at he head of the bench.","Lie facedown on a raised bench; raised enough for your arms to move freely beneath the bench.","Place your toes on the floor in order to stabilise yourself.","Grasp the dumbbells and with a 30 degree bend in your elbows, this is the starting position.","Raise your arms to shoulder height, maintaining a controlled motion.","Return to starting position and repeat."],"img":["0023-relaxation.svg","0023-tension.svg"]},{"id":"rear-deltoid-row-dumbbell","name":"Rear Deltoid Row Dumbbell","eq":"dumbbell","p":["shoulders"],"s":["biceps","traps"],"ins":["Place your right foot on the floor, rest your left knee and hand on a flat bench.","Lean forward so your body\u2019s weight is supported by your left arm and knee.","Keeping your back flat, reach down and pick up the dumbbell with your right hand.","Raise your right arm as close to your chest as possible; while bending and bringing your elbow back as far as you can.","Pause at the top for a moment and then lower the dumbbell in a controlled manner to the starting position.","Switch arms by doing the opposite positioning.","Repeat."],"img":["0024-relaxation.svg","0024-tension.svg"]},{"id":"seated-cable-rows","name":"Seated Cable Row","eq":"cable","p":["lats"],"s":["biceps","lower back"],"ins":["Sit at a low pulley machine with your feet resting against the footrests and your knees slightly bent.","With your abs drawn in and your back straight lean forward slightly to grasp the pulleys with an overhand grip (palms face downwards).","Slowly bring the pulleys back towards your abs while sitting upright, keep your elbows in close to your chest.","Pause for a moment then return slowly return the pulleys to the starting position.","Repeat."],"img":["0025-relaxation.svg","0025-tension.svg"]},{"id":"reverse-grips-bent-over-barbell-rows","name":"Reverse Grips Bent Over Barbell Rows","eq":"barbell","p":["lats"],"s":["biceps"],"ins":["Bend over a barbell at slight angle with your knees bent and your back straight.","Grasp the bar with a reverse grip (palms facing up) and slowly pull the barbell to your abs, keeping your elbows close to your sides.","Pause for a moment at the top.","Return the barbell to the starting position.","Repeat."],"img":["0026-relaxation.svg","0026-tension.svg"]},{"id":"stationary-abdominal-draw-in","name":"Stationary Abdominal Draw In","eq":"bodyweight","p":["abs"],"s":[],"ins":["Get down on a mat on your hands and knees, forming a four point rectangle or square shape.","Keep your back straight and your hips and pelvis in a neutral position.","Draw your abs in, crunching your abs while keeping your back still.","Hold for a moment and then release returning to the starting position.","Repeat."],"img":["0027-relaxation.svg","0027-tension.svg"]},{"id":"rear-deltoid-row-barbell","name":"Rear Deltoid Row Barbell","eq":"barbell","p":["shoulders"],"s":["biceps"],"ins":["Place a barbell on the floor in front of you with the resided weights attached.","With your knees bent and back straight grasp the bar with a wide overhand grip (palms facing downwards).","Keep your chest steady and your arms perpendicular to your chest.","Pull the bar as far up to your chest as you can.","Hold for a moment than lower the bar in a controlled manner.","Repeat."],"img":["0028-relaxation.svg","0028-tension.svg"]},{"id":"t-bar-rows","name":"T-Bar Row","eq":"machine","p":["lats"],"s":["biceps","shoulders"],"ins":["Place your feet on either side of a T-Bar Machine.","With your knees slightly bent and abs drawn in, grasp the handles with a narrow grip.","Bend at the waist so your chest is parallel to the floor, this is starting position. Slowly pull the bar to your chest, as high as you can.","Pause at the top for a moment and then lower the bar to starting position.","Repeat"],"img":["0029-relaxation.svg","0029-tension.svg"]},{"id":"barbell-shrugs","name":"Barbell Shrug","eq":"barbell","p":["traps"],"s":[],"ins":["Stand on the floor with your abs drawn in and your back straight.","Grasp a barbell with a grip a little wider than shoulder width at arms length.","Drop your shoulders as much as possible to start.","Raise your shoulder as high as possible.","Pause for a moment at the top and then return to starting position in a controlled motion.","Repeat."],"img":["0030-relaxation.svg","0030-tension.svg"]},{"id":"incline-shoulder-press-dumbbell","name":"Incline Shoulder Press Dumbbell","eq":"dumbbell","p":["shoulders"],"s":[],"ins":["Lie down on an incline bench with your feet flat on the floor and grasp the dumbbells.","With your elbows bent raise your arms up until in line with your shoulders this is your starting position.","With your abs drawn in, raise the dumbbells as high as you are able above your shoulders.","Lower the dumbbells in a slow controlled manner to starting position."],"img":["0031-relaxation.svg","0031-tension.svg"]},{"id":"bent-over-rear-deltoid-raise-with-head-on-bench","name":"Bent Over Rear Deltoid Raise With Head On Bench","eq":"dumbbell","p":["shoulders"],"s":[],"ins":["Rest your forehead on an incline bench in oder to stabilise your movements so you are bent over with your back parallel to the floor, draw your abs in.","Grasp dumbbells in your hands with your arms straight and elbows slightly bent ensuring they are not locked.","Slowly raise the dumbbells up to shoulder height.","Pause for a moment and then return to the starting position.","Repeat."],"img":["0032-relaxation.svg","0032-tension.svg"]},{"id":"front-dumbbell-raise","name":"Front Dumbbell Raise","eq":"dumbbell","p":["shoulders"],"s":[],"ins":["Stand with a dumbbell in each hand with an overhand grip, your feet shoulder width apart and your abs drawn in.","Keeping each arm straight raise your left arm to just above shoulder height.","Pause for a moment then in a controlled motion lower the weight to starting position and repeat with your right arm.","<h3></h3>"],"img":["0033-relaxation.svg","0033-tension.svg"]},{"id":"internal-cable-rotation","name":"Internal Cable Rotation","eq":"cable","p":["shoulders"],"s":["biceps"],"ins":["Sit on the floor with your body close to low cable pulley.","Grasp the pulley with your left arm and position your elbow bent at 90 degree angle.","Pull the cable towards your body and internally rotate your shoulder until your forearm is across your abs.","Return to starting position.","Repeat with right arm."],"img":["0034-relaxation.svg","0034-tension.svg"]},{"id":"seated-rear-lateral-cable-raise","name":"Seated Rear Lateral Cable Raise","eq":"cable","p":["shoulders"],"s":[],"ins":["Sit on the edge of a bench with your feet on the floor in front of you.","Rest your chest on your thighs with your back straight, grasp the cable pulleys with opposite hands.","Raise your upper arms to shoulder height. Pause at the top for a moment.","Lower your arms to the starting position in a controlled motion.","Repeat."],"img":["0035-relaxation.svg","0035-tension.svg"]},{"id":"lying-one-arm-rear-lateral-raise","name":"Lying One Arm Rear Lateral Raise","eq":"dumbbell","p":["shoulders"],"s":[],"ins":["Lay face down on a flat bench high enough for your arms to hang down to the floor.","Place a dumbbell at your side.","Your other hand not grasping the dumbbell can be on the floor stabilising your movements.","Grasp the dumbbell in your hand and raise your upper arm to shoulder height.","Keep your arm straight and perpendicular to your chest with a slight bend in the elbow.","In a slow controlled manner lower your arm to starting position."],"img":["0037-relaxation.svg","0037-tension.svg"]},{"id":"one-arm-dumbbell-shoulder-press","name":"One Arm Dumbbell Shoulder Press","eq":"dumbbell","p":["shoulders"],"s":["triceps","biceps"],"ins":["Stand with your feet shoulder width apart, back straight and abs drawn in.","Grasp a dumbbell in your hand and lift it with a bent elbow to your shoulder height to start.","Lift the dumbbell straight up till your arm is fully extended overhead.","Lower in a controlled manner and return to starting position.","Repeat."],"img":["0038-relaxation.svg","0038-tension.svg"]},{"id":"one-arm-upright-row","name":"One Arm Dumbbell Upright Row","eq":"dumbbell","p":["shoulders"],"s":["traps"],"ins":["Stand near a post or other stable tall object. With your one hand, hold the post.","Grasp the dumbbell in your other hand with a pronated grip (palms facing backwards).","Place the dumbbell in front of your thigh, this is starting position.","Lift the dumbbell upward to your shoulder with your elbow pointing away from your body in a rowing motion.","Lower your arm to starting position and repeat."],"img":["0039-relaxation.svg","0039-tension.svg"]},{"id":"smith-machine-shoulder-shrugs","name":"Smith Machine Shoulder Shrugs","eq":"smith machine","p":["shoulders"],"s":[],"ins":["Place the barbell at waist height.","Stand with your feet shoulder width apart and your abs drawn in.","Grasp the bar with an overhand grip and straightened arms.","As you lift the bar allow the weight to pull your shoulders down, shrug your shoulders up and to the back.","Hold for a moment and then return to starting position."],"img":["0041-relaxation.svg","0041-tension.svg"]},{"id":"bench-press","name":"Barbell Bench Press","eq":"barbell","p":["chest"],"s":["triceps","shoulders"],"ins":["Lie on a flat bench with your feet flat on the floor, keep your back flat on the bench.","Grasp the bar a little wider than shoulder width apart.","Raise the barbell above your body and move it over the middle of your chest, this is your starting position.","Lower the bar down so it just touches your chest.","Raise the bar till your arms are fully extended and your elbows are locked.","Return to starting position."],"img":["0042-relaxation.svg","0042-tension.svg"]},{"id":"incline-bench-press","name":"Incline Barbell Bench Press","eq":"barbell","p":["chest"],"s":["triceps"],"ins":["Lie flat on an incline bench set at a 45 degree angle, with your feet shoulder width apart.","Grasp the bar a little wider than shoulder width apart.","Raise the barbell above your body and move it over the middle of your chest, this is your starting position.","Lower the bar down so it just touches your chest.","Raise the bar straight up till your arms are fully extended and your elbows are locked.","Return to starting position."],"img":["0043-relaxation.svg","0043-tension.svg"]},{"id":"incline-bench-press-with-bands","name":"Incline Bands Bench Press","eq":"band","p":["chest"],"s":["biceps"],"ins":["Securely fasten the band under the leg of a flat bench, near your head.","Lie flat on the bench with your feet flat on the floor in order to stabilise your movements.","Grasp one end of the band in each hand and starting with your hands at chest level.","Press upwards so your arms are fully extended.","With a slow controlled motion return to starting position."],"img":["0044-relaxation.svg","0044-tension.svg"]},{"id":"bent-arm-pullover","name":"Bent Arm Pullover","eq":"barbell","p":["chest"],"s":["lats","shoulders","triceps"],"ins":["Lie flat on a bench with your head hanging slightly over the end and your feet flat on the floor.","Hold a barbell with a close grip (approximately 14\u201d), keep your elbows in throughout the exercise.","Starting with your arms fully extended over your chest, slowly lower the bar in an arc over your head and towards the floor.","Pull the bar back up to chest height in a slow controlled manner and return to starting position.","Repeat."],"img":["0045-relaxation.svg","0045-tension.svg"]},{"id":"dumbbell-bent-arm-pullover","name":"Dumbbell Bent Arm Pullover","eq":"dumbbell","p":["chest"],"s":["shoulders","triceps","lats"],"ins":["Lie flat on a bench with your head hanging slightly over the end and your feet flat on the floor.","Hold a dumbbell with both hands, keep your elbows in throughout the exercise.","Starting with your arms fully extended over your chest, slowly lower the dumbbell in an arc over your head and towards the floor.","Pull the dumbbell back up to chest height in a slow controlled manner and return to starting position.","Repeat."],"img":["0046-relaxation.svg","0046-tension.svg"]},{"id":"cable-crossover","name":"Cable Crossover","eq":"cable","p":["chest"],"s":["shoulders"],"ins":["Attach the cable pulley to shoulder height.","Grasp the pulley in both hands and stand approximately one foot in front of the weight stacks, with one foot slightly in front of the other.","With a slight bend in your elbows bring your hand together in front of your chest on downward angle.","When your hands meet at the midpoint of your chest, hold for a moment.","With a slow controlled motion return to starting position."],"img":["0048-relaxation.svg","0048-tension.svg"]},{"id":"close-grip-barbell-bench-press","name":"Close Grip Barbell Bench Press","eq":"barbell","p":["chest"],"s":["triceps","shoulders"],"ins":["Lie on a flat bench with your feet flat on the floor, keep your back flat on the bench.","Grasp the bar a close grip (approximately 14\u201d apart).","Raise the barbell above your body and move it over the middle of your chest, this is your starting position.","Lower the bar down so it just touches your chest.","Raise the bar till your arms are fully extended and your elbows are locked.","Return to starting position."],"img":["0049-relaxation.svg","0049-tension.svg"]},{"id":"crossover-bands","name":"Crossover with Bands","eq":"band","p":["chest"],"s":["shoulders","biceps"],"ins":["Secure an exercise to a post (or secure pole) and hold it in each hand.","Step forward so the band has some tension, facing away from the post.","Your arms at mid chest height and out to the side, palms facing forward this is your starting position.","Bring your hands together in front of you.","Hold this for a moment and then in a controlled motion return to starting position."],"img":["0050-relaxation.svg","0050-tension.svg"]},{"id":"decline-barbell-bench-press","name":"Decline Barbell Bench Press","eq":"barbell","p":["chest"],"s":["triceps","shoulders"],"ins":["Lie on a decline bench with your head lower than your feet.","Grasp the bar at a grip 3-6 inches wider than your shoulders.","Raise the bar above your chest, keeping your elbows close in.","Slowly and with control lower the bar straight to your lower chest.","Raise the bar back up to starting position with the bar just above your chest.","Repeat."],"img":["0051-relaxation.svg","0051-tension.svg"]},{"id":"decline-dumbbell-bench-press","name":"Decline Dumbbell Bench Press","eq":"dumbbell","p":["chest"],"s":["triceps","shoulders"],"ins":["Grasp the dumbbells your hands and lie on a decline bench with your head lower than your feet.","Raise the dumbbells above your chest, bringing your elbows close in, this is your starting position.","Slowly and with control lower the dumbbells to either side of your lower chest.","Raise the dumbbells back up to starting position."],"img":["0052-relaxation.svg","0052-tension.svg"]},{"id":"decline-dumbbell-flys","name":"Decline Dumbbell Flys","eq":"dumbbell","p":["chest"],"s":["shoulders"],"ins":["Lie on a decline bench with your head lower than your body and your feet firmly on the ground.","With dumbbells together above your shoulders and your arms straight out above you as your starting position.","Keeping your arms straight and with a slight bend in your elbows lower the dumbbells down towards the floor in an arc, up until just above your shoulders.","Return to the starting position in a slow controlled manner.","Repeat."],"img":["0053-relaxation.svg","0053-tension.svg"]},{"id":"chest-dips","name":"Chest Dip","eq":"bodyweight","p":["chest"],"s":["triceps","shoulders"],"ins":["Stand in between the parallel bars.","Grip the handles of the parallel bars and push yourself up to the starting position with straightened arms.","With your elbows close to your body keep your hips straight, lower your body forward by bending your elbows so your chest is leading as you go down.","Raise yourself back up to the starting position and repeat.","Repeat."],"img":["0054-relaxation.svg","0054-tension.svg"]},{"id":"bench-press-dumbbell","name":"Dumbbell Bench Press","eq":"dumbbell","p":["chest"],"s":["shoulders","triceps"],"ins":["Grasp the dumbbells in each hand and lie on a flat bench with your feet firmly on the ground.","Extend your arms up over your chest with your palms facing forwards.","Press the dumbbells up over your chest till your arm are fully extended this is your starting position.","Bend your elbows to a 90 degree angle so your upper arms are parallel with the floor.","Slowly lower the dumbbells as low as comfortable along your chest.","With a controlled motion return back to your starting position.","Repeat."],"img":["0055-relaxation.svg","0055-tension.svg"]},{"id":"dumbbell-flys","name":"Dumbbell Fly","eq":"dumbbell","p":["chest"],"s":["shoulders","triceps"],"ins":["Lie on a flat bench with a dumbbell in each hand and your feet firmly on the ground.","Lift the dumbbells over your chest extending your arms fully with a slight bend in your elbows, this is your starting position.","Keeping a slight bend in your elbows, lower the dumbbells to the floor in an arc like motion.","Slowly return the dumbbells over your chest to the starting position in a controlled motion.","Repeat."],"img":["0056-relaxation.svg","0056-tension.svg"]},{"id":"flat-bench-cable-flys","name":"Flat Bench Cable Flys","eq":"cable","p":["chest"],"s":["shoulders"],"ins":["<h3>\u00a0Steps</h3>","Lie on flat bench between two cable towers and your feet firmly on the ground.","Grasp a pulley in each hand with your palms facing up.","With a slight bend in your elbows, squeeze your chest and pull the cables together meeting in the middle of your chest.","Hold for a moment and then slowly lower your hands back to starting position at bench height.","<h3>Tip</h3>","Ensure your back and hips stay in contact with the bench at all times during this exercise."],"img":["0057-relaxation.svg","0057-tension.svg"]},{"id":"barbell-front-raise-pullover","name":"Barbell Front Raise and Pullover","eq":"barbell","p":["chest"],"s":["triceps","shoulders"],"ins":["Lie on a flat bench and grasp a barbell using a medium grip (about 15\u201d apart).","Place the barbell on your upper thighs and lock your arms straight with a slight bend in your elbows.","Draw your abs in and keeping your back flat on the bench, raise your arms up in an arc over and behind your head (as if you were performing a reverse pullover).","Slowly return the barbell to the starting position on your thighs."],"img":["0058-relaxation.svg","0058-tension.svg"]},{"id":"hammer-grip-incline-bench-press","name":"Dumbbell Bench Press (Incline, Hammer Grip)","eq":"dumbbell","p":["chest"],"s":["shoulders","triceps"],"ins":["Grasp a dumbbell in each hand and lay on an incline bench set at a 45 degree angle.","Keep your feet flat on the floor and your back against the bench at all times.","Using a hammer grip (with your palms facing each other), lift the weights to shoulder height on either side of your chest.","Extend your arms fully and press the dumbbells up.","Slowly return the dumbbells to the starting position at the sides of your chest."],"img":["0059-relaxation.svg","0059-tension.svg"]},{"id":"incline-cable-flys","name":"Incline Cable Flys","eq":"cable","p":["chest"],"s":["biceps","triceps","forearms"],"ins":["Place an incline bench set at a 45 degree angle between two cable towers.","Grasp a pulley in each hand with your palms facing up.","With a slight bend in your elbows, squeeze your chest and pull the cables in an arc so they meet together in the middle of your chest.","Hold for a moment and then slowly lower your hands back to starting position at along the same arc."],"img":["0060-relaxation.svg","0060-tension.svg"]},{"id":"dumbbell-incline-bench-press","name":"Incline Dumbbell Bench Press","eq":"dumbbell","p":["chest"],"s":["triceps","shoulders"],"ins":["Lie on an incline bench which has been set to an incline of 45 degrees.","Start with the dumbbells at shoulder height, your arms wide and elbows pointing down to the floor.","Grasp the dumbbells with a grip so your palms face each other.","Raise your arms up over your chest bringing the dumbbells closer together as they meet over your chest, as if you were clapping.","Slowly return the dumbbells to starting position."],"img":["0061-relaxation.svg","0061-tension.svg"]},{"id":"incline-dumbbell-flys","name":"Incline Dumbbell Flys","eq":"dumbbell","p":["chest"],"s":["shoulders"],"ins":["Lie on an incline bench set a 45 degree angle with a dumbbell in each hand and your feet firmly on the ground.","Lift the dumbbells over your chest extending your arms fully and your palms facing each other.","Keeping a slight bend in your elbows, lower the dumbbells towards the floor in and arc like motion.","Slowly return to starting position."],"img":["0062-relaxation.svg","0062-tension.svg"]},{"id":"incline-flys-twist","name":"Incline Flys with a Twist","eq":"dumbbell","p":["chest"],"s":["shoulders"],"ins":["Lie on an incline bench set at a 45 degree angle with a dumbbell in each hand and your feet flat on the ground.","Start with the dumbbells out to the sides of your chest, parallel to the floor as you would a regular Fly.","Raise the dumbbells over your chest in and arc, at the top turn your pinky finger in so they are facing each other.","Slowly return to starting position.","Repeat."],"img":["0063-relaxation.svg","0063-tension.svg"]},{"id":"wide-grip-decline-barbell-pullover","name":"Wide Grip Decline Barbell Pullover","eq":"barbell","p":["chest"],"s":[],"ins":["Lie on a decline bench with your feet higher than your head and your feet firmly on the ground.","Grasp the barbell with an extra wide grip (your hands near the plates) and starting at you\u2019re your upper thighs raise the barbell in an arc over your head towards the floor.","Slowly return the barbell to starting position on your thighs.","Repeat."],"img":["0064-relaxation.svg","0064-tension.svg"]},{"id":"machine-bench-press","name":"Machine Bench Press","eq":"machine","p":["chest"],"s":["triceps","shoulders"],"ins":["Adjust the machine so that you are sitting with the bars at chest height.","Place your hands on the bars and place your feet on the foot rest.","Press out, extending your arms as far as possible in a steady motion.","Pause for a moment and then return slowly to starting position."],"img":["0066-relaxation.svg","0066-tension.svg"]},{"id":"barbell-neck-press","name":"Barbell Neck Press","eq":"barbell","p":["chest"],"s":["biceps"],"ins":["Lie on a flat bench with you feet planted firmly on the floor.","Grasp the bar a little wider than shoulder width apart.","Raise the barbell above your body and move it to the top of your chest, near your neck.","This is your starting position.","Lower the bar down so it just touches the top of your chest.","Raise the bar till your arms are fully extended and your elbows are locked.","Return to starting position.","Repeat."],"img":["0067-relaxation.svg","0067-tension.svg"]},{"id":"one-arm-bench-press","name":"One Arm Dumbbell Bench Press","eq":"dumbbell","p":["chest"],"s":["triceps","shoulders"],"ins":["Lie flat on a bench with your feet placed firmly on the floor and your abs drawn in.","Grasp the dumbbell in one hand and bring it up to the side of your chest, this is starting position.","Extend your arm, pressing the dumbbell up till your arm is straight and your elbow locked.","Using slow controlled movements, lower the weight to starting position.","Switch arms after completing reps with one arm.","Repeat."],"img":["0068-relaxation.svg","0068-tension.svg"]},{"id":"bosu-ball-push-up","name":"Bosu Ball Push Up","eq":"ball","p":["chest"],"s":["shoulders","abs","triceps"],"ins":["Place the Bosu ball flat side down on the floor.","Kneel on the floor with your arms fully extended on the ball, and body straight.","Keeping your abs drawn in and your body straight, by bending your elbows lower your chest to the ball.","Pause for a moment and then return to starting position.","Repeat."],"img":["0069-relaxation.svg","0069-tension.svg"]},{"id":"one-arm-barbell-floor-press","name":"One Arm Barbell Floor Press","eq":"barbell","p":["chest"],"s":["triceps"],"ins":["Lie flat on your back with your knees bent and your feet firmly on the floor.","Draw in your abs and contract your lats, and glutes.","Have your partner hand you the bar and with your bicep parallel to the floor lift and extend your arm fully so it is straight.","Return to the starting position.","Complete reps and switch arms."],"img":["0070-relaxation.svg","0070-tension.svg"]},{"id":"one-arm-flat-bench-flys","name":"One Arm Flat Bench Flys","eq":"dumbbell","p":["chest"],"s":[],"ins":["Lie on a flat bench with your free hand holding the bench.","Grasp the dumbbell in your other hand and with your forearm parallel to the floor raise your arm in an arc the middle of your chest.","Once the dumbbell is at the middle of your chest line, slowly lower is along the same path to starting position.","Repeat."],"img":["0071-relaxation.svg","0071-tension.svg"]},{"id":"one-armed-biased-push-up","name":"One Armed Biased Push Up","eq":"ball","p":["chest"],"s":["triceps","biceps","shoulders","abs"],"ins":["Arrange the ball so that as you begin the exercise, one hand on the Bosu ball and the other on the floor.","Place the ball flat side down on the floor.","Kneel on the floor with your arms fully extended on the dome, and body straight.","Keeping your abs drawn in and your body straight, lower your chest to the ball.","Pause for a moment and then return to starting position.","Repeat."],"img":["0072-relaxation.svg","0072-tension.svg"]},{"id":"push-up-feet-elevated","name":"Bench Push Up (Feet Elevated)","eq":"bodyweight","p":["chest","shoulders"],"s":["triceps"],"ins":["Place your feet on a bench at least 18\u201d off the ground.","Make sure the tops of your feet are flush against the bench.","Place your hands on the floor slightly wider than shoulder width apart.","With your hands directly under your shoulders, press up from the floor, keeping your back and neck in a straight line so you are looking forward during the entire exercise.","Once your arms are fully extended pause and then with slow controlled movements lower yourself to the floor again."],"img":["0075-relaxation.svg","0075-tension.svg"]},{"id":"push-ups-with-feet-on-exercise-ball","name":"Exercise ball Push Up","eq":"ball","p":["chest"],"s":["triceps","shoulders"],"ins":["Place your feet and shins flat on an Exercise Ball.","Place your arms in front of you at shoulder width apart, place your hands under your arms and press up from the ground until your arms are fully extended.","Pause at the top for a moment and steady your balance.","Slowly return to the starting position with your chest lowered towards the ground."],"img":["0076-relaxation.svg","0076-tension.svg"]},{"id":"push-ups","name":"Push-Up","eq":"bodyweight","p":["chest"],"s":["triceps","shoulders"],"ins":["Start with a basic push up, lay face down on the floor, or a mat; with your feet together curled slightly so you rise onto the ball of your feet.","Place you hands shoulder width apart on the either side of your chest.","Draw your abs in.","Inhale as you raise your body up till your arms are straight.","Keep your head and neck level with your body (don\u2019t look up or down) and don\u2019t allow your back to rise or fall.","Exhale out as you lower your body back to the ground.","Repeat."],"img":["0077-relaxation.svg","0077-tension.svg"]},{"id":"smith-machine-bench-press","name":"Smith Machine Bench Press","eq":"smith machine","p":["chest"],"s":["shoulders","triceps"],"ins":["Place a flat bench in the middle of the Smith Machine, with the bar in line with the middle of your chest.","Lying on the bench, grasp the bar at shoulder width apart.","Unlatch the bar and slowly lower the bar to your chest.","Extend your arms fully and raise the bar to the starting position.","Repeat."],"img":["0078-relaxation.svg","0078-tension.svg"]},{"id":"straight-arm-dumbbell-pullover","name":"Straight Arm Dumbbell Pullover","eq":"dumbbell","p":["chest"],"s":["triceps","lats","shoulders"],"ins":["Lie on a flat bench with your feet flat on the floor and your head at the end of the bench.","Grasp a dumbbell and raise it over your chest.","Keeping your elbows as straight as possible, lower the weight in an arc over your head and as low to the ground as possible with out any pain.","Return to starting position.","Repeat."],"img":["0079-relaxation.svg","0079-tension.svg"]},{"id":"incline-dumbbell-press","name":"Incline Dumbbell Press","eq":"dumbbell","p":["chest"],"s":["triceps","shoulders"],"ins":["Set and incline bench at a 45 degree angle.","Start with the dumbbells at shoulder height, your arms wide and elbows pointing down to the floor.","Raise your arms up over your chest bringing the dumbbells closer together as they meet over your chest.","Slowly return the dumbbells to starting position.","Repeat."],"img":["0080-relaxation.svg","0080-tension.svg"]},{"id":"smith-machine-incline-bench-press","name":"Incline Smith Machine Bench Press","eq":"smith machine","p":["chest"],"s":["shoulders","triceps"],"ins":["Place an incline bench at a 45 degree angle in the middle of the Smith Machine.","Align the bench so the bar is across the upper portion of your chest.","Grasp the bar with a shoulder width grip.","Unlock the bar and slowly lower the weight to your chest, do not bounce the bar on your chest.","With slow controlled movements, raise the bar back to the starting position."],"img":["0081-relaxation.svg","0081-tension.svg"]},{"id":"wide-grip-bench-press","name":"Barbell Bench Press (Wide Grip)","eq":"barbell","p":["chest"],"s":["triceps","shoulders"],"ins":["Lie flat on a bench with your feet flat on the floor.","Place your hands wider than shoulder width apart on the bar and lift it off the rack, this is starting position.","Bring the bar over your chest and lower it till it is just above your body.","Extend your arms upward and raise the bar straight up.","Pause for a moment and with slow controlled movement, return the bar to starting position.","Repeat."],"img":["0082-relaxation.svg","0082-tension.svg"]},{"id":"wide-grip-decline-bench-press","name":"Barbell Bench Press (Decline, Wide Grip)","eq":"barbell","p":["chest"],"s":["triceps","shoulders"],"ins":["Lie on a decline bench with your head lower than your feet.","Place your hands wider than shoulder width apart on the bar and lift it off the rack.","Bring the bar over your chest and lower it till it is just above the lower portion of your chest, this is starting position.","Extend your arms upward and raise the bar straight up.","Pause for a moment and then lower the bar to starting position.","Repeat."],"img":["0083-relaxation.svg","0083-tension.svg"]},{"id":"decline-chest-press","name":"Decline Chest Press","eq":"machine","p":["chest"],"s":["shoulders","triceps"],"ins":["Adjust the seat of the machine so that the handles are near the lower portion of your chest.","Slowly press the handles forward until your hands are fully extended, do not lock your elbows.","Pause for a moment and then with a controlled movement lower your hands back to starting position."],"img":["0085-relaxation.svg","0085-tension.svg"]},{"id":"body-row","name":"Body Row","eq":"bodyweight","p":["chest"],"s":["abs","traps","upper back"],"ins":["Lie under a bar so that the bar is at mid chest level and your feet are firmly on the floor.","Draw your abs in and keep your back flat.","Using your arms, lift and row your body towards the bar.","Pause for a moment and with slow controlled movements lower your self back to starting position.","Repeat."],"img":["0086-relaxation.svg","0086-tension.svg"]},{"id":"pull-ups","name":"Pull-Up","eq":"bodyweight","p":["lats"],"s":["biceps"],"ins":["Grab the pull-up bar with the palms facing forward using the prescribed grip.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion.","<h3>\u00a0Tip</h3>","Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar."],"img":["0087-relaxation.svg","0087-tension.svg"]},{"id":"narrow-parallel-grip-chin-ups","name":"Narrow Parallel Grip Chin-ups","eq":"bodyweight","p":["shoulders","lats"],"s":["upper back","abs"],"ins":["Grasp the bar with an supinated (overhand) grip so that your palms are facing.","Let your body hang from the bar with your arms straight.","Slowly pull yourself up so that your chin is higher than the bar.","With a controlled movement lower yourself to the starting position.","Repeat"],"img":["0090-relaxation.svg","0090-tension.svg"]},{"id":"wide-grip-chin-up","name":"Wide Grip Chin Up","eq":"bodyweight","p":["traps"],"s":["biceps"],"ins":["Grasp a chin up bar with a slightly wider than shoulder width grip.","Keeping your body straight pull yourself up and to one side of the bar.","Lower your body back down to the starting position.","Raise yourself to the other side of the bar.","Repeat."],"img":["0091-relaxation.svg","0091-tension.svg"]},{"id":"straight-arm-push-down","name":"Straight Arm Push Down","eq":"cable","p":["lats"],"s":["triceps"],"ins":["Grasp wide grip pull down bar with a wide grip so your hands are on the portion of the bar which curves down.","Stand erect with your abs drawn in.","Keeping a slight bend in your elbows and your wrist steady pull the bar down from the starting position to your upper thighs.","With a controlled motion bring the bar back up to starting position."],"img":["0092-relaxation.svg","0092-tension.svg"]},{"id":"underhand-pull-downs","name":"Underhand Pull Down","eq":"cable","p":["lats"],"s":["biceps"],"ins":["Sitting upright with your abs drawn in grasp a Pull Down bar with and underhand grip shoulder width apart.","Pull the bar down till the bar reaches your upper chest, keeping your elbows close to your body.","Slowly return the bar to the starting position.","Repeat."],"img":["0093-relaxation.svg","0093-tension.svg"]},{"id":"upright-band-rows","name":"Upright Band Rows","eq":"band","p":["lats"],"s":["triceps","shoulders"],"ins":["Stand on the band so that the handles are level with your upper thigh.","With your back straight and abs drawn in raise your hands upward to your collarbone.","Your elbows and arms should be parallel with the floor.","Slowly lower your arms and return to starting position."],"img":["0094-relaxation.svg","0094-tension.svg"]},{"id":"underhand-pull-down","name":"Underhand Pull Down","eq":"cable","p":["lats"],"s":["biceps"],"ins":["Sitting upright with your abs drawn in grasp a Pull Down bar with and underhand grip shoulder width apart.","Pull the bar down till the bar reaches your upper chest, keeping your elbows close to your body.","Slowly return the bar to the starting position.","Repeat."],"img":["0095-relaxation.svg","0095-tension.svg"]},{"id":"v-bar-pull-down","name":"V Bar Pull Down","eq":"cable","p":["lats"],"s":["biceps"],"ins":["Attach a V bar to the pull down pulley of a cable machine.","Sitting upright with your abs drawn grasp the bar with an overhand grip, your palms facing in.","Pull the bar straight down to your upper chest.","Pause for a moment after touching the chest and then slowly return the bar to starting position.","Repeat."],"img":["0096-relaxation.svg","0096-tension.svg"]},{"id":"pullover-stability-ball-weight","name":"Pullover On Stability Ball With Weight","eq":"dumbbell","p":["shoulders"],"s":["upper back","traps"],"ins":["Grasp a Barbell or Dumbbell and sit on a Ball with your feet firmly placed on the floor.","Lower your body so your upper abs are the only part of your body supported on the Ball.","Bring the Barbell or Dumbbell to your chest with your arms extend.","In an arcing motion raise the Barbell or Dumbbell over and behind your head towards the floor.","Return to starting position.","Repeat."],"img":["0098-relaxation.svg","0098-tension.svg"]},{"id":"barbell-dead-lifts","name":"Barbell Deadlift","eq":"barbell","p":["lower back"],"s":["hamstrings","calves"],"ins":["Stand with your feet shoulder width apart so that your feet are under the bar.","Keeping your back straight bend at the waist, allow some bend in your knees.","Grasp the par with an overhand grip approximately 16 inches apart.","Straighten your back as you hold the bar at arm\u2019s length.","Bend over again lowering the bar to just above the floor."],"img":["0099-relaxation.svg","0099-tension.svg"]},{"id":"smith-machine-dead-lifts","name":"Smith Machine Deadlift","eq":"smith machine","p":["lower back"],"s":["hamstrings","calves"],"ins":["Stand with your feet shoulder width apart so that your feet are under the bar.","Keeping your back straight bend at the waist, allow some bend in your knees.","Grasp the par with an overhand grip approximately 16 inches apart.","Straighten your back as you hold the bar at arm\u2019s length.","Bend over again lowering the bar to just above the floor."],"img":["0100-relaxation.svg","0100-tension.svg"]},{"id":"barbell-good-mornings","name":"Barbell Good Mornings","eq":"barbell","p":["lower back"],"s":["hamstrings"],"ins":["Place a barbell across your shoulders.","Keeping your head up and your back completely straight, bend at the waist until your back is parallel with the floor.","Return to starting position.","Repeat."],"img":["0101-relaxation.svg","0101-tension.svg"]},{"id":"smith-machine-good-mornings","name":"Smith Machine Good Mornings","eq":"smith machine","p":["lower back"],"s":["hamstrings"],"ins":["Place a barbell across your shoulders.","Keeping your head up and your back completely straight, bend at the waist until your back is parallel with the floor.","Return to starting position.","Repeat."],"img":["0102-relaxation.svg","0102-tension.svg"]},{"id":"hyperextensions","name":"Hyperextensions","eq":"other","p":["lower back"],"s":["hamstrings","abs"],"ins":["Adjust the hyperextension bench so that your ankles are tucked under the footpads and your thighs are flat across the top pad.","With your arms folded across your chest and your back straight, slowly bend at the waist towards the floor, keeping your back flat.","Slowly return to the starting position.","Repeat."],"img":["0103-relaxation.svg","0103-tension.svg"]},{"id":"back-extension-stability-ball","name":"Back Extension on Stability Ball","eq":"ball","p":["lower back"],"s":["abs","hamstrings"],"ins":["Lie prone (on your stomach) on a Stability Ball with your toes firmly planted on the floor for balance.","With your hands across your chest or at your ears, raise your chest off the ball so you are hyperextending your spine.","Slowly return your chest to the ball.","Repeat."],"img":["0104-relaxation.svg","0104-tension.svg"]},{"id":"supermans","name":"Supermans","eq":"bodyweight","p":["lower back"],"s":["abs"],"ins":["Lie flat on your stomach with your arms stretched out in front of you.","Raise your arms and legs off the floor and hold this position for 2 seconds.","Return to the starting position on the floor.","Repeat."],"img":["0105-relaxation.svg","0105-tension.svg"]},{"id":"dumbbell-dead-lifts","name":"Dumbbell Deadlift","eq":"dumbbell","p":["lower back"],"s":["calves","hamstrings"],"ins":["Grasp 2 dumbbells and stand with your feet shoulder width apart.","Keeping your back straight bend at the waist, allow some bend in your knees.","Grasp the dumbbells with an overhand grip in each hand.","Straighten your back as you hold the dumbbells at arm\u2019s length.","Bend over again lowering the dumbbells to just above the floor.","Return to starting position.","Repeat."],"img":["0107-relaxation.svg","0107-tension.svg"]},{"id":"bridging","name":"Bridging","eq":"bodyweight","p":["glutes"],"s":["abs"],"ins":["Lie on your back with your knees bent and your feet flat on the floor.","Lift up hips and bum off the floor as you draw your abs in and keep your gluts tight."],"img":["0109-relaxation.svg","0109-tension.svg"]},{"id":"body-leg-lifts","name":"Body Leg Lifts","eq":"bodyweight","p":["glutes"],"s":["hamstrings"],"ins":["Using a post or tall weight bench for balance stand straight with your abs drawn in.","Raise one off the ground and behind you while standing on the other leg.","Slowly lower the leg and raise it again while flexing the gluts.","Repeat with your other leg."],"img":["0111-relaxation.svg","0111-tension.svg"]},{"id":"one-legged-cable-kickback","name":"One Legged Cable Kickback","eq":"cable","p":["glutes"],"s":["hamstrings"],"ins":["Standing at a cable tower attach an ankle cuff to a low pulley.","Facing the weight stack, with a slight bend in your knees and your abs drawn in","Slowly kick your ankle back in and arc as high as you are able to.","Return to starting position and switch ankles."],"img":["0112-relaxation.svg","0112-tension.svg"]},{"id":"side-plank","name":"Side Plank","eq":"bodyweight","p":["obliques"],"s":[],"ins":["Lay on one side of your body with your legs straight and your forearm perpendicular to your body in front of you.","Drawing your abs in, slowly raise yourself up so you are balanced on your feet and your forearm.","Hold this position and slowly return back to the starting position.","Repeat on other side."],"img":["0113-relaxation.svg","0113-tension.svg"]},{"id":"barbell-lunges","name":"Barbell Lunge","eq":"barbell","p":["hamstrings"],"s":["glutes","quads","calves"],"ins":["Start by placing a barbell across your upper back, using a grip slightly wider than your shoulders.","Stand with your feet about 8 inches apart, toes facing forward.","Take a step forward (2-3 feet) keeping your abs drawn in and your upper body straight.","Slowly lower one knee down as if kneeling while keeping your other knee bent at a 90 degree angle, do not let your knee touch the ground.","Lower your body so that your rear knee is just above the floor and hold for a moment before returning to the starting position.","Repeat on other side."],"img":["0114-relaxation.svg","0114-tension.svg"]},{"id":"dumbbell-lunges","name":"Dumbbell Lunge","eq":"dumbbell","p":["hamstrings"],"s":["glutes","quads","calves"],"ins":["Grasp a dumbbell in each hand.","Stand with your feet about 8 inches apart, toes facing forward.","Take a step forward (2-3 feet) keeping your abs drawn in and your upper body straight.","Slowly lower one knee down as if kneeling while keeping your other knee bent at a 90 degree angle, do not let your knee touch the ground.","Lower your body so that the rear knee is just above the floor and hold for a moment before returning to the starting position.","Repeat on opposite side."],"img":["0115-relaxation.svg","0115-tension.svg"]},{"id":"flutter-kicks","name":"Flutter Kicks","eq":"other","p":["hamstrings"],"s":["quads"],"ins":["Lie face down on a bench with your hips on the edge, hold onto the bench with your hands.","Allow your legs and toes hang down.","Draw your abs in, squeeze your gluts and hamstrings.","Kick each back and up while keeping your hips on the bench.","Alternate kicking each leg."],"img":["0116-relaxation.svg","0116-tension.svg"]},{"id":"lying-leg-curl-machine","name":"Lying Leg Curl","eq":"machine","p":["hamstrings"],"s":[],"ins":["Lie face down on a leg curl machine and place your heels under the roller pad.","Grasp the grips with your hands for support and slowly curl your ankles up towards your back.","Hold for a moment and then return to starting position.","Repeat."],"img":["0117-relaxation.svg","0117-tension.svg"]},{"id":"romanian-dead-lift","name":"Romanian Deadlift","eq":"barbell","p":["hamstrings"],"s":["calves","quads","glutes"],"ins":["Place a barbell in front of your feet on the ground.","Grasp the barbell with a grip a bit wider than shoulder width apart.","Bend your knees slightly, keeping your hips and back straight.","Lift the bar straight up concentrating on using your hips as you stand.","Stand with the bar resting against your thighs.","Lower the bar to the floor with a slight bend in your knees flexing your hips back for stability."],"img":["0118-relaxation.svg","0118-tension.svg"]},{"id":"seated-leg-curl","name":"Seated Leg Curl","eq":"machine","p":["hamstrings"],"s":[],"ins":["Adjust the machine so that the footpad is just above your heels.","Sit upright with your abs drawn in and your legs in front of you.","Slowly curl your legs back towards you and hold for a moment.","With controlled movement return to the starting position."],"img":["0119-relaxation.svg","0119-tension.svg"]},{"id":"standing-leg-curls","name":"Standing Leg Curls","eq":"machine","p":["hamstrings"],"s":[],"ins":["Standing at a leg curl machine adjust the rear footpad so it is just above your ankle.","Grasp the handles of the machine for support and draw your abs in.","Raise your foot up towards your back slowly.","Return to the starting position and chance legs."],"img":["0120-relaxation.svg","0120-tension.svg"]},{"id":"walking-lunges","name":"Walking Dumbbell Lunges","eq":"dumbbell","p":["hamstrings"],"s":["quads","glutes","calves"],"ins":["Start by grasping a dumbbell in each hand.","Stand with your feet about 8 inches apart, toes facing forward.","Take a lunge forward keeping your abs drawn in and your upper body straight.","Slowly lower one knee down as if kneeling while keeping your other knee bent at a 90 degree angle, do not let your knee touch the ground.","Lower your body to just above the floor and hold for a moment before pushing off with the back foot.","Step through and repeat the exercise with the other leg."],"img":["0121-relaxation.svg","0121-tension.svg"]},{"id":"barbell-squat","name":"Barbell Squat","eq":"barbell","p":["quads"],"s":["hamstrings"],"ins":["Lifting a barbell off of a weight rack, position it on your shoulders.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position."],"img":["0122-relaxation.svg","0122-tension.svg"]},{"id":"hack-squat-machine","name":"Hack Squat","eq":"machine","p":["quads"],"s":["hamstrings","calves"],"ins":["Lie face up on a Hack Squat machine with your shoulders against the pad.","Place your feet facing forward at slightly less than shoulder width apart with your toes point slightly outward.","Release the dock levers and place your hands on the hand grips.","Drawing your abs in, extend your body standing upright.","Lower your body to a squatting position so you knees are bent as if you were sitting down.","Return to the starting position."],"img":["0123-relaxation.svg","0123-tension.svg"]},{"id":"smith-machine-squats","name":"Smith Machine Squats","eq":"smith machine","p":["quads"],"s":["calves","glutes","hamstrings"],"ins":["Set the height of the barbell to shoulder height.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift over\u00a0your toes (this will cause you to loose balance).","Pause in the downward squatting position and slowly return upright to the starting position.","If needed, a\u00a0pad on the bar or towel on your shoulders can help improve your grip and the reduce the discomfort of the bar against your back. First practice the squat without any weight to allow yourself to become comfortable with the movements."],"img":["0124-relaxation.svg","0124-tension.svg"]},{"id":"hack-squat-with-barbell","name":"Barbell Hack Squat","eq":"barbell","p":["quads"],"s":["hamstrings"],"ins":["This is another variation of the basic Squat that focuses primarily\u00a0on the quadriceps or thigh muscles.","Place the barbell on the floor just behind your legs and stand with your feet shoulder width apart with\u00a0your toes pointing forward.","With your feet firmly placed on the floor, reach down and grasp the barbell from behind with an overhand grip.","Lift the barbell by extending your hips and knees, taking care\u00a0not to lock your knees.","Lower yourself (squat) down until your thighs are parallel to the floor.","Slowly raise yourself up to starting position."],"img":["0125-relaxation.svg","0125-tension.svg"]},{"id":"smith-machine-hack-squat","name":"Smith Machine Hack Squat","eq":"smith machine","p":["quads"],"s":["hamstrings","glutes"],"ins":["This is another variation of the basic Squat that focuses primarily on the\u00a0quadriceps, or thigh muscles, while using the Smith Machine.","Adjust the bar to a low setting just above your ankles.","Stand with the bar on the floor just behind your legs, with your feet shoulder width apart and your toes pointing forward.","With your feet firmly placed on the floor reach down and grasp the bar from behind, with an overhand grip.","Lift the bar by extending your hips and knees, taking care not to lock your knees.","Lower yourself (squat) down until your thighs are parallel to the floor.","Slowly raise yourself up to starting position.","Note: Your knees should be moving in the same direction as your feet."],"img":["0126-relaxation.svg","0126-tension.svg"]},{"id":"leg-press","name":"Leg Press","eq":"machine","p":["quads"],"s":["calves","hamstrings"],"ins":["Adjust the seat of the machine so that your feet comfortably reach the crosspiece with a slight bend in your knees.","To begin, press your feet forward at a shoulder width stance and release the safety locks.","Slowly lower the weight towards your body, keeping your abs drawn in and your knees moving in the same direction as your feet to a 90 degree angle.","Do not lock your knees or bounce the weight."],"img":["0127-relaxation.svg","0127-tension.svg"]},{"id":"rear-lunges-with-barbell","name":"Rear Barbell Lunges","eq":"barbell","p":["quads"],"s":["abductors","calves","glutes","hamstrings"],"ins":["Place a barbell on a rack at chest height.","Lift the barbell of of the rack and onto your shoulders, gripping the bar slightly wider than shoulder width apart.","Stand with your feet approximately 8 inches apart with your toes pointing forward.","Slowly take a step backward with your right leg.","Keeping your abs drawn in and your upper body straight, lower your body until your left knee is almost on the ground.\u00a0You may choose to\u00a0place a mat or towel under your knee.","Hold for a moment and then return to starting position."],"img":["0128-relaxation.svg","0128-tension.svg"]},{"id":"rear-lunges-with-dumbbell","name":"Rear Dumbbell Lunges","eq":"dumbbell","p":["quads"],"s":["calves","hamstrings","glutes","abductors"],"ins":["This is an advanced version of a lunge.","Grasp a dumbbell in each hand.","Stand with your feet approximately 8 inches apart with your toes pointing forward.","Slowly take a step backward with your right leg.","Keeping your abs drawn in and your upper body straight, lower your body until your left knee is almost on the ground.\u00a0You may choose to place a mat or towel under your knee.","Hold for a moment and then return to starting position."],"img":["0129-relaxation.svg","0129-tension.svg"]},{"id":"squats-using-dumbbells","name":"Dumbbell Squat","eq":"dumbbell","p":["quads"],"s":["hamstrings","calves"],"ins":["This is a\u00a0great overall exercise for the lower body that uses dumbbells instead of a barbell. Beginners may find this version easier to perform.","Grasp a dumbbell in each hand.","Stand with\u00a0feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Note: Practicing the squat without any weight will allow you to become comfortable with the movements."],"img":["0130-relaxation.svg","0130-tension.svg"]},{"id":"side-squats-with-barbell","name":"Barbell Side Squats","eq":"barbell","p":["quads"],"s":["abductors","hamstrings"],"ins":["Place a barbell on your shoulders and grasp it with a wide grip.","Stand with your feet wide apart, with the foot of the leg you will be leaning towards angled out.","Bring your lower body to your foot by bending the hip and knee of your lead leg, and keeping your other leg fairly straight.","Return to the starting position and switch legs."],"img":["0131-relaxation.svg","0131-tension.svg"]},{"id":"single-leg-squat-with-barbell","name":"Single Leg Squat with Barbell","eq":"barbell","p":["quads"],"s":["calves","hamstrings"],"ins":["This is an advanced exercise and modification of the basic squat. Mastery of the squat is recommended before attempting this exercise.","Place a barbell on your back, above your shoulders with a wide grip.","Cross the lower leg above the knee of your supporting leg (the leg you will squat with).","Squat down as low as you are able.","Slowly return to an upright position by straightening your hip and knee.","Switch legs and repeat."],"img":["0132-relaxation.svg","0132-tension.svg"]},{"id":"squat-to-bench-with-barbell","name":"Barbell Squats (to Bench)","eq":"barbell","p":["quads"],"s":["glutes","calves","hamstrings"],"ins":["This is s great overall exercise for the lower body. There are many variations on the squat, this one uses a bench to remind you how far down to squat.","Place a bench behind you.","Lifting a barbell off of a weight rack, position it on your shoulders.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in, descend slowly and squat down, bending at the knees and hips.","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance). Do not sit on the bench.","Pause in the downward position and slowly return upright to the starting position.","A pad on the bar or towel on your shoulders can help improve your grip and reduce discomfort of the bar against your back. Practice the squat without any weight to allow yourself to become comfortable with the movements. Do not sit on the bench during the exercise."],"img":["0133-relaxation.svg","0133-tension.svg"]},{"id":"step-ups-with-barbell","name":"Barbell Step Ups","eq":"barbell","p":["quads"],"s":["hamstrings","calves"],"ins":["Place a bench, box or step in front of you.","Grasp a barbell with a wide grip and place it across your shoulders.","With your left leg, step up on the bench, and follow by stepping up with your right leg.","Step down with your left leg and then your right leg.","Repeat starting with your right leg.","Note: Use a lighter weight until you are used to the motion of this exercise."],"img":["0134-relaxation.svg","0134-tension.svg"]},{"id":"hip-adduction","name":"Hip Adduction","eq":"cable","p":["quads"],"s":["abductors"],"ins":["Stand alongside a cable pulley stack and attach a cuff to the pulley and\u00a0your ankle.","Step away from the stack, holding onto the stack for support.","Standing firm on the foot not attached to the cable and slowly abduct, or pull, your cuffed ankle in front of your stabilizing leg.","Repeat and switch ankles."],"img":["0135-relaxation.svg","0135-tension.svg"]},{"id":"squat-to-bench-with-dumbbells","name":"Dumbbells Squats (to Bench)","eq":"dumbbell","p":["quads"],"s":["calves","hamstrings","glutes"],"ins":["This is a great overall exercise for the lower body. There are many variations on the squat, this one uses a bench to remind you how far down to squat.","Place a bench behind you.","Grasp a dumbbell in each hand.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in descend slowly by squatting down and bending at the knees and hips.","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Practice the squat without any weight to allow yourself to become comfortable with the movements. Do not sit on the bench during the exercise."],"img":["0136-relaxation.svg","0136-tension.svg"]},{"id":"step-ups-with-dumbbells","name":"Dumbbell Step Ups","eq":"dumbbell","p":["quads"],"s":["calves","hamstrings"],"ins":["Place a bench, box or step in front of you.","Grasp a dumbbell in each hand.","With your left leg, step up on the bench, and follow by stepping up with your right leg.","Step down with your left leg and then your right leg.","Repeat starting with your right leg.","Note:\u00a0Use a lighter weight until you are used to the motion of this exercise."],"img":["0137-relaxation.svg","0137-tension.svg"]},{"id":"front-squat-with-barbell","name":"Front Squat with Barbell","eq":"barbell","p":["quads"],"s":["hamstrings","calves"],"ins":["The Front Squat works the same muscles as the rear squat without placing the weight of the bar on your shoulders. This exercise can be a good substitute for people with back and neck injuries.","Place the barbell on your upper chest, resting it across your front deltoids and holding it with your arms crossed securely.","Keep your head and back straight, abs drawn in and toes pointing slightly outward.","Slowly \u201csquat\u201d down so your upper thighs are parallel to the floor.","Slowly return to the starting position.","Note: Practice the squat without any weight to allow yourself to become comfortable with the movements."],"img":["0138-relaxation.svg","0138-tension.svg"]},{"id":"front-squat-to-bench-with-barbells","name":"Front Squat to Bench with Barbells","eq":"barbell","p":["quads"],"s":["hamstrings","calves"],"ins":["The Front Squat works the same muscles as the rear squat without placing the weight of the bar on your shoulders. This exercise can be a good substitute for people with back and neck injuries. By using a bench you remind yourself how far to squat down","Steps","Place a bench behind you.","Place the barbell on your upper chest, resting it across your front deltoids and holding it with your arms crossed securely.","Keep your head and back straight, abs drawn in and your toes pointing slightly outward.","Slowly \u201csquat\u201d down so your upper thighs are parallel to the floor.","Slowly return to the starting position.","Note:\u00a0Practice the squat without any weight to allow yourself to become comfortable with the movements. Do not sit on the bench during the exercise."],"img":["0139-relaxation.svg","0139-tension.svg"]},{"id":"iron-cross-with-dumbbells","name":"Dumbbell Iron Cross","eq":"dumbbell","p":["quads"],"s":["traps","glutes","shoulders","lower back","hamstrings"],"ins":["With a dumbbell in each hand, stand in a low squat stance, your feet shoulder width arms held out in front of you with your palms facing in.","Standing upright, move your arms out and away from your body forming a \u201cT\u201d or \u201ccross\u201d.","Note: Do this exercise with light weights until you are comfortable with the movements."],"img":["0140-relaxation.svg","0140-tension.svg"]},{"id":"jefferson-squats-with-barbell","name":"Barbell Jefferson Squats","eq":"barbell","p":["hamstrings"],"s":[],"ins":["This is a rarely used exercise which is without question one of the best exercises for building and shaping the inner thighs.","Place a barbell between your legs so it is perpendicular to your feet.","Grasp the barbell with one hand in front of you and one hand behind you with an overhand grip.","Squatting down so your thighs are parallel to the floor slowly lift the weight up between your legs as you stand.","Slowly return to a starting position just above the floor."],"img":["0141-relaxation.svg","0141-tension.svg"]},{"id":"leg-extensions","name":"Leg Extension","eq":"machine","p":["quads"],"s":[],"ins":["Adjust the seat so that your knees have full range of motion and that the footpad fits over your legs, just above your ankles.","Grasp the handles with your hands for support, keeping your hip and back against the bench.","Slowly extend your legs until your knees are straight, but do not lock your knees.","Hold for a moment and then with controlled movements return to the starting position.","Note:\u00a0Use controlled movements for this exercise, do not swing the weight up."],"img":["0142-relaxation.svg","0142-tension.svg"]},{"id":"narrow-stance-leg-press","name":"Narrow Stance Leg Press","eq":"machine","p":["quads"],"s":["calves","hamstrings"],"ins":["This is a variation of the leg press which targets more of the external muscles of the legs by moving your feet closer together.","Sit on a leg press machine with your feet on the crosspiece 6 inches apart, with your toes pointed slightly outward.","Grasp the handles on the side of the machine and release the locks.","Keeping your abs drawn in, bend your knees and bring the weight as far as possible towards your chest.","Hold this position for a moment and then slowly return the weight to starting position.","Note: Do not lock your knees at the top."],"img":["0143-relaxation.svg","0143-tension.svg"]},{"id":"lying-squat","name":"Lying Squat","eq":"machine","p":["quads"],"s":["calves","hamstrings"],"ins":["Adjust the shoulder rack of the machine so that your feet comfortably reach the crosspiece with a slight bend in your knees.","To begin, press your feet forward and release the safety locks.","Slowly lower the weight towards your body, keeping your abs drawn in and your knees moving in the same direction as your feet to a 90 degree angle.","Do not lock your knees or bounce the weight."],"img":["0144-relaxation.svg","0144-tension.svg"]},{"id":"narrow-stance-hack-squats","name":"Narrow Stance Hack Squats","eq":"machine","p":["quads"],"s":["hamstrings","calves"],"ins":["Like the Hack Squat, this exercise works the muscles of the leg. The narrow stance targets the external muscles more efficiently.","Lie face up on a Hack Squat machine with your shoulders against the pad.","Place your feet facing forward at a distance of 6 inches apart with your toes point slightly outward.","Release the dock levers and place your hands on the handgrips.","Drawing your abs in, extend your body standing upright.","Lower your body to a squatting position so your knees are bent as if you were sitting down.","Return to the starting position."],"img":["0145-relaxation.svg","0145-tension.svg"]},{"id":"narrow-stance-squat-with-barbell","name":"Narrow Stance Squat with Barbell","eq":"barbell","p":["quads"],"s":["glutes","calves","hamstrings"],"ins":["A great overall exercise for the lower body. This version of the Squat targets and defines more of the externals leg muscles.","Lifting a barbell off of a weight rack, position it on your shoulders.","Place your feet about 6 inches apart with your knees and toes pointed slightly outward.","Drawing your abs in, descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Notes: A pad on the bar or towel on your shoulders can help improve your grip and reduce the discomfort of the bar against your back. Practice the squat without any weight to allow yourself to become comfortable with the movements."],"img":["0146-relaxation.svg","0146-tension.svg"]},{"id":"one-leg-squat-with-barbell","name":"One Leg Squat with Barbell","eq":"barbell","p":["quads"],"s":["calves","hamstrings","glutes"],"ins":["The One Leg Squat isolates the muscles of the leg for optimal exercise. This exercise is also used to build or rebuild strength after injury.","Place a bench or box 12-18 inches tall behind you.\u00a0The taller the box the greater the difficulty of the exercise.","Lifting a barbell off of a weight rack, position it on your shoulders.","Place one foot up on the bench, and your other foot firmly on the floor 2-3 feet in front you.","Drawing your abs in descend slowly by bending your front knee and hip as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toe (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Switch legs and repeat.","Notes:\u00a0A pad on the bar or towel on your shoulders can help improve your grip and reduce the discomfort of the bar against your back.\u00a0Practice the squat without any weight to allow yourself to become comfortable with the movements."],"img":["0147-relaxation.svg","0147-tension.svg"]},{"id":"one-arm-snatch-with-barbell","name":"One Arm Snatch with Barbell","eq":"barbell","p":["quads"],"s":["shoulders","hamstrings","lower back","abs","traps","calves"],"ins":["This is an advanced exercise that works most of the muscles of the body.","Exercises like this are used to develop functional strength for sports that require strong hands.","Stand with your feet shoulder width apart, and a slight bend in your knees.","Grasp the bar with an overhead grip.","Starting with the barbell held slightly above the knees (hang position), lift the weight up over your head (step 1) then back to shoulder height (step 2) and finally back to starting position between near your knees."],"img":["0148-relaxation.svg","0148-tension.svg"]},{"id":"one-arm-side-deadlift-with-barbell","name":"Barbell Dead Lift (One Arm Side)","eq":"barbell","p":["quads"],"s":["abs","glutes","calves","hamstrings"],"ins":["This is an advanced exercise that works most of the muscles of the body. Exercises like this are used to develop functional strength for sports that require strong hands.","Stand besides a barbell placed on the floor.","Grasp the bar with an overhand grip in the center.","Crouching down as if your were performing a squat, bend down so your thighs are parallel with the floor.","Extend your legs slowly as you straighten your body up, drawing in your abs as you rise.","Note: Perform this exercise with an empty bar to become familiar with the movement before adding weights."],"img":["0150-relaxation.svg","0150-tension.svg"]},{"id":"overhead-squat-with-barbell","name":"Overhead Squat with Barbell","eq":"barbell","p":["quads"],"s":["glutes","calves","hamstrings","shoulders","lower back"],"ins":["Stand with your feet a bit wider than shoulder width apart with your toes pointed slightly outward.","Grasp a barbell using a wide side snatch grip with your arms and elbows fully extended.","Keeping the bar overhead, bend your knees and lower your body until your thighs are parallel with the floor.","Return to starting position.","Notes: Keep your feet firmly planted on the floor throughout this exercise. Keep your abs drawn in your back tight and your chest up you perform this exercise."],"img":["0151-relaxation.svg","0151-tension.svg"]},{"id":"pile-squat-with-dumbbell","name":"Pile Squat with Dumbbell","eq":"dumbbell","p":["quads"],"s":["hamstrings","calves"],"ins":["Stand with your feet 2-4 inches wider than your shoulders, with your toes pointed out at a 45 degree angle.","Grasp a dumbbell with both hands in the center of your body.","Keep your knees slightly bent and your back straight.","Squat down as if you were going to sit in a chair, bringing your thighs parallel to the floor.","With a controlled motion return to starting position.","Notes: Keep your feet planted firmly on the floor throughout this exercise."],"img":["0152-relaxation.svg","0152-tension.svg"]},{"id":"speed-squats-with-barbell","name":"Barbell Speed Squats","eq":"barbell","p":["quads"],"s":["calves","glutes","hamstrings"],"ins":["This version of the squat uses an empty barbell and moves at a faster pace than the standard squat. This is a good exercise for building speed and conditioning used in running and jumping sports.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in, descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Note:\u00a0Keep your feet firmly planted on the floor throughout this exercise."],"img":["0154-relaxation.svg","0154-tension.svg"]},{"id":"squats-with-exercise-bands","name":"Exercise Bands Squats","eq":"band","p":["quads"],"s":["calves","glutes","hamstrings"],"ins":["Stand with your feet on the exercise bands with your feet shoulder width apart.","Grasp the handles of the bands and pull them up to your shoulders.","With your abs drawn in, squat down until your thighs are parallel with the floor.","Slowly return to the starting position.","Note:\u00a0Keep your feet firmly planted on the floor throughout this exercise."],"img":["0155-relaxation.svg","0155-tension.svg"]},{"id":"thigh-abductor","name":"Thigh Abductor","eq":"machine","p":["quads"],"s":["hamstrings"],"ins":["Sit on the machine and place your knees against the pads.","Draw your abs in and \u201cabduct\u201d or move your thighs apart against the pads.","Slowly return to the starting position and repeat.","Note: Maintain the same level of resistance throughout this exercise for best results."],"img":["0156-relaxation.svg","0156-tension.svg"]},{"id":"thigh-adductor","name":"Thigh Adductor","eq":"machine","p":["quads"],"s":["hamstrings"],"ins":["Sit on the machine and place your knees against the pads.","Draw your abs in and \u201cadduct\u201d or move your thighs together.","Slowly return to the starting position and repeat.","Note:\u00a0Maintain the same level of resistance throughout this exercise for best results."],"img":["0157-relaxation.svg","0157-tension.svg"]},{"id":"weighted-sissy-squat-with-weight-plate","name":"Weighted Sissy Squat with Weight Plate","eq":"other","p":["quads"],"s":[],"ins":["Don't\u00a0let the name of this exercise fool you, it is a an assisted squat which effectively works the quadriceps (leg muscles).","Grasp a weight rack or bar for support with one arm and hold a free weight plate across your chest with your other hand.","With your abs drawn in, squat down lowering your body to the floor until your knees are almost fully flexed.","Return to the starting position.","Note:\u00a0Keep your feet placed firmly on the floor throughout this exercise."],"img":["0158-relaxation.svg","0158-tension.svg"]},{"id":"wide-stance-squat-with-barbell","name":"Wide Stance Squat with Barbell","eq":"barbell","p":["quads"],"s":["calves","hamstrings"],"ins":["Lifting a barbell off of a weight rack, position it on your shoulders.","Stand with your feet wider than shoulder width apart (about 30 inches apart) with your toes pointing out.","Drawing your abs in descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Note:\u00a0A pad on the bar or towel on your shoulders can help improve your grip and reduce the discomfort of the bar against your back. Practice the squat without any weight to allow yourself to become comfortable with the movements."],"img":["0160-relaxation.svg","0160-tension.svg"]},{"id":"zecher-squats","name":"Zecher Squats","eq":"barbell","p":["quads"],"s":["glutes","hamstrings","calves"],"ins":["This variation of squat is similar to a Front Squat, it works to build the upper muscles of the quadriceps (thighs).","Lift a barbell off of a weight rack and place across your chest. Hold the barbell with your arms crossed.","Place your feet slightly wider than shoulder width apart with your knees and toes pointed slightly outward.","Drawing your abs in, descend slowly by bending at the knees and hips as if you are sitting down (squatting).","Lower yourself as far as you can control without letting your body shift towards your toes (this will cause you to loose balance).","Pause in the downward position and slowly return upright to the starting position.","Note:\u00a0Practice the squat without any weight to allow yourself to become comfortable with the movements."],"img":["0161-relaxation.svg","0161-tension.svg"]},{"id":"bench-dips","name":"Bench Dips","eq":"bodyweight","p":["triceps"],"s":["chest"],"ins":["Place two benches parallel to each other 3-4 feet apart.","Sit on one bench and place your feet on the edge of the other bench so that your legs are suspended between the 2 benches.","Cross your feet for support.","Hold onto the bench with your hands for support and slowly lower body towards the floor by bending your elbows.","Pause and then return to starting position.","Note:\u00a0Do not go below a 90 degree angle as this can cause on your shoulders."],"img":["0162-relaxation.svg","0162-tension.svg"]},{"id":"incline-pushdown-with-cable","name":"Incline Pushdown with Cable","eq":"cable","p":["triceps"],"s":[],"ins":["Place an incline bench facing away from a cable pulley.","Attach a short straight bar to the pulley and adjust the height so that your arms can extend fully.","Lie face up on the bench and grasp the bar with a narrow overhand grip.","Keeping your arms straight, slowly push the bar down towards your feet.","Pause at the bottom and then return to starting position.","Note:\u00a0Keep your elbows steady throughout this exercise."],"img":["0163-relaxation.svg","0163-tension.svg"]},{"id":"incline-triceps-extension-with-cable","name":"Incline Cable Triceps Extension","eq":"cable","p":["triceps"],"s":[],"ins":["Place an incline bench facing away from a cable pulley.","Attach a short straight bar to the pulley and adjust the height so that your arms can extend fully.","Lie face up on the bench and grasp the bar with a narrow overhand grip.","Starting with your elbows bent overhead, slowly lower the bar towards your feet.","Pause at the bottom and then return to starting position."],"img":["0164-relaxation.svg","0164-tension.svg"]},{"id":"lying-triceps-extension-with-cable","name":"Lying Tricep Extension with Cable","eq":"cable","p":["triceps"],"s":[],"ins":["Place a flat bench with the end towards a weight stack.","Attach a short straight bar to the pulley and lower the pulley to the bottom of the stack.","Lie face up on the bench and grasp the bar with a narrow overhand grip.","Starting with your arms extended lower the bar towards the bar towards the stack by bending your elbows.","Slowly extend your arms upright and return to the starting position.","Note:\u00a0Keep your elbows level throughout the exercises."],"img":["0165-relaxation.svg","0165-tension.svg"]},{"id":"one-arm-tricep-extension-with-cable","name":"One Arm Tricep Extension with Cable","eq":"cable","p":["triceps"],"s":[],"ins":["Place a cable pulley on the highest setting and adjust a stirrup handle to the pulley.","Stand facing the weight stack and grasp the handle with and underhand grip.","Keep your back straight, your abs drawn in and your knees slightly bent.","Starting at the top, push your arm down until it is straight, feeling the concentration in your tricep.","Slowly return to starting position.","Tips:\u00a0Keep your elbow close to your side while performing this exercise."],"img":["0166-relaxation.svg","0166-tension.svg"]},{"id":"decline-close-grip-bench-to-skull-crusher","name":"Decline Close Grip Bench to Skull Crusher","eq":"barbell","p":["triceps"],"s":["chest"],"ins":["Lay with your back on a flat bench.","Grip a barbell with a close grip 8-12 inches apart.","Keeping your arms close to your sides lower the bar so it touches your chest, approximately an inch below your nipples.","Slowly return to starting position, concentrating on your triceps.","At the top of the exercise bend your arms down towards your head.","Raise the bar back up over your chest and repeat."],"img":["0168-relaxation.svg","0168-tension.svg"]},{"id":"decline-triceps-extension-with-dumbbell","name":"Decline Dumbbell Triceps Extension","eq":"dumbbell","p":["triceps"],"s":[],"ins":["Lay face up on a decline bench with a dumbbell in each hand.","Extend your arms so they are perpendicular to your chest, and keeping your elbows in one place, lower your hands so the dumbbells are lowered near your head.","Slowly return to the starting position."],"img":["0169-relaxation.svg","0169-tension.svg"]},{"id":"decline-ez-bar-triceps-extension-with-barbell","name":"Decline EZ Bar Barbell Triceps Extension","eq":"barbell","p":["triceps"],"s":[],"ins":["Lay face up on a decline bench and grasp an EZ Bar (Curved Barbell).","Extend your arms so they are perpendicular to your chest, and keeping your elbows in one place, lower the bar toward your head.","Slowly return to the starting position."],"img":["0170-relaxation.svg","0170-tension.svg"]},{"id":"tricep-dips","name":"Machine Triceps Dips","eq":"machine","p":["triceps"],"s":["shoulders"],"ins":["Adjust the seat of the machine so that the handles are equal with your elbows.","Grasping the handles, press down with equal pressure until your arms are fully extended.","Pause, and then return to the starting position."],"img":["0171-relaxation.svg","0171-tension.svg"]},{"id":"tricep-dips-using-body-weight","name":"Triceps Dip","eq":"bodyweight","p":["triceps"],"s":["shoulders","chest"],"ins":["Grasp a set of parallel bars and push yourself up to the starting position.","Keeping your elbows close to your body, lower yourself down until your triceps are parallel to the floor.","Slowly raise yourself back to the starting position.","Note:\u00a0Keep your abs drawn in and your body straight during this exercise."],"img":["0172-relaxation.svg","0172-tension.svg"]},{"id":"one-arm-triceps-extension-with-dumbbell","name":"One Arm Dumbbell Triceps Extension","eq":"dumbbell","p":["triceps"],"s":[],"ins":["Sit on a bench with your back straight and your abs drawn in.","Grasp a dumbbell in your hand and place it behind your neck with your elbow bent.","Slowly extend your arm straight up over your head and slowly return to the starting position.","Note: Place your free hand across your chest to help steady yourself during this exercise."],"img":["0173-relaxation.svg","0173-tension.svg"]},{"id":"incline-triceps-extension-with-barbell","name":"Incline Barbell Triceps Extension","eq":"barbell","p":["triceps"],"s":[],"ins":["Grasp a barbell with a close grip (4-6 inches apart).","Lie on an incline bench and hold the bar over your head.","Lower your arms in a slight arc so your forearms are touching your biceps.","Slowly return back to the starting position with the bar over your head."],"img":["0174-relaxation.svg","0174-tension.svg"]},{"id":"jm-press","name":"JM Press","eq":"barbell","p":["triceps"],"s":["shoulders"],"ins":["Lay on a flat bench with your head just at the end of the bench.","Grasp the bar with a medium overhand grip keeping your elbows close to your side, over your sternum (mid chest).","Lower the bar towards your sternum at a regular pace, then pause for a moment.","With a controlled but rapid pace, push the bar back to starting position.","Note: The bar should move in straight line, up and down."],"img":["0175-relaxation.svg","0175-tension.svg"]},{"id":"kneeling-triceps-extension-with-cable","name":"Kneeling Triceps Concentration Extension with Cable","eq":"cable","p":["triceps"],"s":[],"ins":["Attach a stirrup handle to a cable pulley and adjust the pulley up high.","Kneeling on your left knee, with the left side of your body turned towards the machine, keep your right leg bent and the upper portion of your thigh parallel to the floor.","With your right elbow and upper arm pressed against your inner thigh just above your knee, pull the cable down towards the floor in a slight arcing motion.","Slowly to return to starting position.","Repeat and switch arms.","Note: Keep all of your body still except the arm you are exercising."],"img":["0176-relaxation.svg","0176-tension.svg"]},{"id":"kneeling-triceps-extension-with-cable-2","name":"Cable Triceps Extension (Kneeling)","eq":"cable","p":["triceps"],"s":[],"ins":["Place a bench sideways in front of a high pulley machine.","Grasp a straight bar with an over head grip.","Kneel on the floor in front of the bench with your back straight and your head down.","With your elbows and forearms above your head, push the bar down in an arc so that your forearms are touching the bench.","Note: Keep your abs drawn in and your back straight as you perform this exercise."],"img":["0177-relaxation.svg","0177-tension.svg"]},{"id":"low-triceps-extension-with-cable","name":"Cable Triceps Extension (Low)","eq":"cable","p":["triceps"],"s":[],"ins":["Attach a rope to the cable pulley at of a seated row station.","Lie on your back on the bench with your head facing the weight stack.","Grasp the rope with your palms facing each other and raise your arms over your chest, with your forearms parallel to the floor at a 90 degree angle.","Slowly extend your arms upward squeezing your triceps.","Return to starting position."],"img":["0178-relaxation.svg","0178-tension.svg"]},{"id":"lying-close-grip-triceps-extension-behind-the-head-with-barbell","name":"Barbell Triceps Extension (Lying, Close Grip, Behind the Head)","eq":"barbell","p":["triceps"],"s":[],"ins":["You can use a barbell or EZ (curl) bar to further concentrate the benefit to your triceps.","Lie flat on a bench on your back.","Grasp the bar with a grip approximately 8 inches apart and lower the bar behind your head.","Keeping the bar parallel with the floor, bend your arms down in an arc so the bar moves in a direction under your head.","Slowly return to starting position."],"img":["0179-relaxation.svg","0179-tension.svg"]},{"id":"lying-close-grip-triceps-press-to-chin-with-barbell","name":"Lying Close Grip Triceps Press to Chin with Barbell","eq":"barbell","p":["triceps"],"s":[],"ins":["Lie on a flat bench on your back, with your head at one end.","Grasp a bar with a close grip, approximately 6 inches apart.","Raise the bar straight up over your shoulders, keeping your elbows close in.","Slowly lower the bar in an arc towards your chin.","Return the bar to the starting position."],"img":["0180-relaxation.svg","0180-tension.svg"]},{"id":"lying-triceps-extension-with-dumbbells","name":"Lying Dumbbell Triceps Extension","eq":"dumbbell","p":["triceps"],"s":[],"ins":["Lay on a flat bench with your head at one end and your feet planted firmly on the floor.","Grasp a dumbbell with both hands with palms facing up.","Raise dumbbell over your body. Your arms will be pointed towards the ceiling.","While keeping your upper arms and elbows still, lower the dumbbell in an arc behind your head.","Slowly raise the dumbbell back to the starting position."],"img":["0181-relaxation.svg","0181-tension.svg"]},{"id":"lying-triceps-extension-across-face-with-dumbbell","name":"Dumbbell Triceps Extension (Lying, Across Face)","eq":"dumbbell","p":["triceps"],"s":[],"ins":["This is an advanced exercise and should be avoided by beginners.","Lay on a flat bench with your head at one end and your feet planted firmly on the floor.","Grasp a dumbbell in each hand with palms facing up.","Raise dumbbells over your body. Your arms will be pointed towards the ceiling.","While keeping your upper arms and elbows still, lower the dumbbell slowly over your face bending only your elbow.","Slowly raise the dumbbell back to the starting position and repeat with your other arm.","Note: Do not perform this exercise if your arms are fatigued, as you are lifting the weight over your face."],"img":["0182-relaxation.svg","0182-tension.svg"]},{"id":"lying-triceps-press-with-barbell","name":"Lying Triceps Press with Barbell","eq":"barbell","p":["triceps"],"s":["chest"],"ins":["Lie on a flat bench with your head at one end.","Grasp an EZ or Curl bar with an overhand grip.","Raise the bar straight up over your shoulders, taking care to keep your elbows in close.","Slowly lower the bar in an arc over your head.","Return the bar to the starting position.","Note: Keep your arms straight throughout this exercise moving only your elbows."],"img":["0183-relaxation.svg","0183-tension.svg"]},{"id":"lying-two-arm-triceps-extension-with-dumbbell","name":"Dumbbell Triceps Extension (Lying Two Arm)","eq":"dumbbell","p":["triceps"],"s":[],"ins":["Lie flat on a bench, on your back, with your head at one end.","Grasp a dumbbell in each hand and raise them at arms length over your shoulders.","Lower the dumbbells in an arc bending your elbows until your forearms are touching your biceps.","Slowly return to the starting position."],"img":["0184-relaxation.svg","0184-tension.svg"]},{"id":"old-school-reverse-extensions","name":"Old School Reverse Extensions","eq":"barbell","p":["triceps"],"s":[],"ins":["Lie down on a bench, on your back, with your head at one end.","Grasp a barbell with an underhand grip.","Move your arms beyond your head,\u00a0keeping them in a straight line.","Bending only your elbows, slowly lower and raise the barbell."],"img":["0185-relaxation.svg","0185-tension.svg"]},{"id":"single-arm-triceps-extension-with-dumbbell","name":"Dumbbell Triceps Extension (Single Arm, Pronated)","eq":"dumbbell","p":["triceps"],"s":[],"ins":["This is an advanced exercise to isolate and work the tricep (back of the arm) muscles.","Lie flat in a bench with your head at one end and your feet placed firmly on the floor.","Grasp a dumbbell in one hand and raise it to a position above your chest, with your palm facing your feet.","Place your free hand under the shoulder to support your other arm.","Slowly lower the weight moving only your forearm and elbow towards and away from your chest.","Repeat with your other arm.","Note: Practice this exercise with light weight to get used to the movements."],"img":["0186-relaxation.svg","0186-tension.svg"]},{"id":"single-arm-supinated-triceps-extension-with-dumbbell","name":"Dumbbell Triceps Extension (Single Arm, Supinated)","eq":"dumbbell","p":["triceps"],"s":[],"ins":["Lie flat in a bench with your head at one end and your feet placed firmly on the floor.","Grasp a dumbbell in one hand and raise it to a position above your chest, with your palm facing the floor.","Place your free hand under the shoulder to support your other arm. Slowly bend your elbow over your head with the weight moving only your forearm and elbow.","Return to the starting position and repeat with your other arm.","Note: Practice this exercise with light weight to get used to the movements."],"img":["0187-relaxation.svg","0187-tension.svg"]},{"id":"close-triceps-pushup","name":"Close Triceps Pushup","eq":"bodyweight","p":["triceps"],"s":["chest"],"ins":["This version of the Pushup isolates the tricep (back of the arm) muscles.","Kneel down on the floor or a mat, placing your hand thumbs together and raise your up on your toes.","Draw your abs in and keep your back and neck in a straight line.","Slowly lower your body towards the floor, by bending your arms, until you are nearly touching the floor.","In a controlled manner raise your body back up to the starting position."],"img":["0188-relaxation.svg","0188-tension.svg"]},{"id":"reverse-grip-triceps-pushdown","name":"Reverse Grip Triceps Pushdown","eq":"cable","p":["triceps"],"s":[],"ins":["Stand in front of a cable machine and attach a bar to a high pulley.","Grasp the handle with palms facing up.","Keeping your elbows at your side, pull the handle down towards your thighs.","Pause for a moment and then return to the starting position.","Note: You may want to stager one foot in front of the other for a better stance."],"img":["0189-relaxation.svg","0189-tension.svg"]},{"id":"reverse-triceps-bench-press-with-barbell","name":"Barbell Bench Press (Reverse Triceps)","eq":"barbell","p":["triceps"],"s":["chest"],"ins":["Lie on a flat bench with your head at one end and your feet placed firmly on the floor.","Grasp a barbell with palms facing your head about 16 inches apart.","Move the bar over your chest (about 1 inch below your nipples).","Extend your arms fully raising the bar fully and then lower the bar to the starting position."],"img":["0190-relaxation.svg","0190-tension.svg"]},{"id":"seated-one-arm-triceps-extension-with-dumbbell","name":"Dumbbell Triceps Extension (Seated, One Arm)","eq":"dumbbell","p":["triceps"],"s":[],"ins":["Sit on the edge of a bench with your feet flat on the floor.","Hold a dumbbell in your right hand.","Bring your right arm up to your side so the dumbbell is almost parallel to your chest, keeping your lower arm vertical.","Press your arm back in arc.","Return to the starting position repeat and switch arms."],"img":["0191-relaxation.svg","0191-tension.svg"]},{"id":"seated-two-arm-triceps-extension-with-dumbbell","name":"Dumbbell Triceps Extension (Seated, Two Arm)","eq":"dumbbell","p":["triceps"],"s":[],"ins":["Sit on the edge of a bench with your feet flat on the floor.","Hold a dumbbell in each hand.","Bring your arms up to your side so the dumbbell is almost parallel to your chest, keeping your lower arm vertical.","Press your arm back in arc towards your back.","Return to the starting position repeat and switch arms."],"img":["0192-relaxation.svg","0192-tension.svg"]},{"id":"seated-overhead-triceps-extension-with-barbell","name":"Barbell Triceps Extension (Seated, Overhead)","eq":"barbell","p":["triceps"],"s":[],"ins":["Sit on a short straight back chair with your feet firmly placed on the floor and your back straight.","Grasp an EZ or Curl bar, or barbell with a grip about 6 inches apart.","Raise the bar to arms length above your head and then lower the bar in an arc towards the floor behind your head.","Return to starting position."],"img":["0193-relaxation.svg","0193-tension.svg"]},{"id":"seated-triceps-press-with-dumbbell","name":"Seated Triceps Press with Dumbbell","eq":"dumbbell","p":["triceps"],"s":[],"ins":["Sit on a short, straight backed bench with your feet planted firmly on the floor.","Drawing your abs in,\u00a0grasp the dumbbell with both hands with a palms up grip.","Raise the weight over your head, this is your starting position.","Lower the dumbbell in an arc from above your head to behind your back.","Slowly return to the starting position."],"img":["0194-relaxation.svg","0194-tension.svg"]},{"id":"smith-machine-close-grip-bench-press","name":"Close Grip Smith Machine Bench Press","eq":"smith machine","p":["triceps"],"s":["chest"],"ins":["Place a flat bench in the middle of a Smith Machine.","Using a close grip (about 6 inches apart) unlatch the bar and lower it towards your chest.","Pause just before the bar hits your chest and raise the bar by extending your arms to the starting position."],"img":["0195-relaxation.svg","0195-tension.svg"]},{"id":"bent-over-one-arm-triceps-extension-with-dumbbell","name":"Dumbbell Triceps Extension (Bent-Over, One Arm)","eq":"dumbbell","p":["triceps"],"s":[],"ins":["Stand with your feet shoulder width apart, your abs drawn in and your back straight as you bend at the waist.","Hold a dumbbell in your right hand.","Bring your right arm up to your side so the dumbbell is almost parallel to your chest, keeping your lower arm vertical and press your arm back in arc.","Return to the starting position repeat and switch arms."],"img":["0196-relaxation.svg","0196-tension.svg"]},{"id":"bent-over-two-arm-triceps-extension-with-dumbbell","name":"Dumbbell Triceps Extension (Bent-Over, Two Arm)","eq":"dumbbell","p":["triceps"],"s":[],"ins":["Stand with your feet shoulder width apart, your abs drawn in and your back straight as you bend at the waist until your upper body is parallel to the floor.","Hold a dumbbell in each hand.","Bring your right arm up to your side so the dumbbell in line with your chest, keeping your lower arm vertical and press your arm back in arc.","Return to the starting position repeat and switch arms."],"img":["0197-relaxation.svg","0197-tension.svg"]},{"id":"standing-triceps-extension-2","name":"Standing Dumbbell Triceps Extension","eq":"dumbbell","p":["triceps"],"s":[],"ins":["Stand with your feet shoulder width apart, your back straight and your abs drawn in.","Hold a dumbbell in both hands, with your palms facing up.","Raise the dumbbell over your head and slowly lower the dumbbell in an arc behind your head.","Slowly raise the dumbbell back up to the starting position."],"img":["0198-relaxation.svg","0198-tension.svg"]},{"id":"one-arm-low-pulley-triceps-extension-with-cable","name":"Cable Triceps Extension (One Arm, Low-Pulley)","eq":"cable","p":["triceps"],"s":[],"ins":["Attach a handle to a low cable pulley machine.","Stand with your back to the weight stack, your feet shoulder width apart.","With your left hand, reach behind you and grasp the handle.","Place your right hand on your left elbow for support.","Extend your left arm straight up towards the ceiling and then lower it to the starting position.","Repeat and switch arms."],"img":["0199-relaxation.svg","0199-tension.svg"]},{"id":"standing-overhead-triceps-extension-with-barbell","name":"Barbell Triceps Extension (Standing, Overhead)","eq":"barbell","p":["triceps"],"s":[],"ins":["Stand with your feet shoulder width apart, your back straight and your abs drawn in.","Hold a barbell or EZ Curl bar about 6-8 inches apart with your palms facing up.","Raise the bar over your head and slowly lower the dumbbell in an arc behind your head, towards your back.","Slowly raise the bar back up to the starting position.","Note:\u00a0Keep your elbows close to your head during the exercise"],"img":["0201-relaxation.svg","0201-tension.svg"]},{"id":"standing-triceps-extension-with-towel","name":"Standing Towel Triceps Extension","eq":"bodyweight","p":["triceps"],"s":[],"ins":["Stand with your feet shoulder width apart, your back straight and your abs drawn in.","Hold a towel or rope facing up behind and in back of your head.","Have a partner hold the towel taught during the exercise so the resistance is constant.","Lower your forearms down until they reach your biceps, then slowly raise your arms back up to starting position.","Note:\u00a0Keep your elbows close to your head during the exercise."],"img":["0202-relaxation.svg","0202-tension.svg"]},{"id":"tate-press-with-dumbbell","name":"Tate Press with Dumbbell","eq":"dumbbell","p":["triceps"],"s":[],"ins":["Lay flat on a bench with your head at one end and your feet firmly planted on the floor.","Hold a dumbbell in each hand so your palms are facing your feet.","Drawing your abs in and keeping your back on the bench, raise the weights to the center of your chest.","Without moving elbows, slowly raise your arms up and out contracting your triceps."],"img":["0203-relaxation.svg","0203-tension.svg"]},{"id":"triceps-kickback-with-dumbbell","name":"Triceps Kickback with Dumbbell","eq":"dumbbell","p":["triceps"],"s":[],"ins":["Standing along side a flat bench, bend your left knee and place it on the bench.","Place your left hand on the bench for support, keeping your back at a 45 degree angle.","Hold a dumbbell in your right hand and place your right foot on the floor.","Bend your right arm and raise it up to your shoulder, then with controlled motion kick it back, fully extending your arm.","Switch arms and repeat.","Note: Keep your elbow close to your body during this exercise."],"img":["0204-relaxation.svg","0204-tension.svg"]},{"id":"triceps-pushdown-with-cable","name":"Triceps Pushdown","eq":"cable","p":["triceps"],"s":[],"ins":["Stand in front of a cable machine and attach a short bar to a high pulley.","Grasp the handle with your\u00a0palms facing down.","Draw your abs in and keep your back straight.","Keeping your elbows at your side push the handle down towards your thighs.","Pause for a moment and then return to the starting position.","Note:\u00a0You may want to stager one foot in front of the other for a better stance."],"img":["0205-relaxation.svg","0205-tension.svg"]},{"id":"triceps-pushdown-with-rope-and-cable","name":"Triceps Rope Pushdown","eq":"cable","p":["triceps"],"s":[],"ins":["Stand in front of a cable machine and attach a rope to a high pulley.","Grasp the rope with palms facing down.","Draw your abs in and keep your back straight.","Keeping your elbows at your side push the rope down towards your thighs, if possible \u201csplit\u201d the rope apart at the bottom.","Pause for a moment and then return to the starting position.","Note:\u00a0You may want to stager one foot in front of the other for a better stance."],"img":["0206-relaxation.svg","0206-tension.svg"]},{"id":"triceps-pushdown-with-v-bar-and-cable","name":"Triceps V-Bar Pushdown","eq":"cable","p":["triceps"],"s":[],"ins":["Steps","Stand in front of a cable machine and attach a V Bar to a high pulley.","Grasp the bar with palms facing down.","Draw your abs in and keep your back straight.","Keeping your elbows at your side push the bar down towards your thighs.","Pause for a moment and then return to the starting position.","Note: You may want to stager one foot in front of the other for a better stance."],"img":["0207-relaxation.svg","0207-tension.svg"]},{"id":"weighted-ball-side-bend","name":"Weighted Ball Side Bend","eq":"ball","p":["obliques"],"s":[],"ins":["Lie one side of your torso, and with your waist and hip against a Stability Ball, position your feet on the floor (or against a wall) for support.","With one hand, hold a weight against the side of your head.","Place your free hand across your chest to steady yourself.","Raise your torso up off the ball by flexing your waist.","With controlled movements lower yourself back onto the ball."],"img":["0208-relaxation.svg","0208-tension.svg"]},{"id":"incline-triceps-extensions-with-dumbbell","name":"Incline Dumbbell Triceps Extension","eq":"dumbbell","p":["triceps"],"s":["shoulders"],"ins":["Grasp a dumbbell in each hand and lie against an incline bench, face up with your feet firmly planted on the floor.","Extend your arms over your shoulders with your palms facing each other.","Slowly lower the dumbbells behind your head by bending your elbows.","With a controlled motion raise your arms back up to the starting position."],"img":["0209-relaxation.svg","0209-tension.svg"]},{"id":"triceps-extensions-using-machine","name":"Machine Triceps Extension","eq":"machine","p":["triceps"],"s":[],"ins":["Name: This exercise uses a machine to insure proper range of motion. This is a good exercise for beginners and people rehabilitating from injury.","Adjust the seat height of the machine so your upper arms and elbows lie flat on the pad. Draw your abs in and sit upright with your back straight. With your arms fully extended grasp the handles and pull them towards your body. Hold for a moment and then slowly return to the starting position.","Note:\u00a0Stay seated and keep your feet firmly on the floor throughout this exercise."],"img":["0210-relaxation.svg","0210-tension.svg"]},{"id":"biceps-curls-with-barbell","name":"Barbell Biceps Curl","eq":"barbell","p":["biceps"],"s":["shoulders","forearms"],"ins":["This is a basic exercise for the biceps (arms).","Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a barbell with palms facing up, approximately shoulder width apart.","Lower your arms fully to above your thighs and bending only your elbows, raise the bar to your upper chest.","Pause for a moment and then return to the starting position.","Note:\u00a0Do not swing your hips or back during this exercise."],"img":["0211-relaxation.svg","0211-tension.svg"]},{"id":"standing-biceps-curl-with-cable","name":"Standing Biceps Curl with Cable","eq":"cable","p":["biceps"],"s":["forearms","shoulders"],"ins":["Attach a short bar to a cable pulley to the bottom of the weight stack.","Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp the bar with palms facing up, and hands fairly close together.","Lower your arms fully to above your thighs and bending only your elbows, raise the bar to your upper chest.","Pause for a moment and then return to the starting position.","Note: Do not swing your hips or back during this exercise."],"img":["0212-relaxation.svg","0212-tension.svg"]},{"id":"alternating-hammer-curl-with-dumbbell","name":"Alternating Hammer Curl with Dumbbell","eq":"dumbbell","p":["biceps"],"s":["forearms"],"ins":["Stand with our feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand so your palms are facing each other.","Extend your arms so they are at the sides of your body.","Keeping your elbows locked lift your left arm in an arc towards your left shoulder.","Lower your arm and repeat with your right arm.","Note:\u00a0Do not turn your wrists during this exercise."],"img":["0213-relaxation.svg","0213-tension.svg"]},{"id":"alternating-incline-curl-with-dumbbell","name":"Alternating Incline Curl with Dumbbell","eq":"dumbbell","p":["biceps"],"s":[],"ins":["Adjust an incline bench to a 45 degree angle.","Grasp a dumbbell in each hand and sit back on the bench with your feet firmly planted on the floor.","Allow your arms to hang down at your sides.","Keeping your elbow straight, raise your right arm up towards your head.","In a controlled manner lower the weight and repeat with your left arm."],"img":["0214-relaxation.svg","0214-tension.svg"]},{"id":"lying-incline-curl-with-barbell","name":"Lying Incline Curl with Barbell","eq":"barbell","p":["biceps"],"s":[],"ins":["Adjust an incline bench to a 45 degree angle.","Grasp a barbell with a shoulder width grip and lean face down against the bench, with your feet resting on the floor for support.","Allow your arms to hang down at your sides.","Keeping your elbows straight, raise the bar up towards your head, contracting your biceps.","In a controlled manner lower the weight and repeat.","Note: Practice steady movements in this exercise, be careful not to let your arms sway."],"img":["0215-relaxation.svg","0215-tension.svg"]},{"id":"hammer-curls-with-rope-and-cable","name":"Hammer Curls with Rope and Cable","eq":"cable","p":["biceps"],"s":[],"ins":["Using the rope with the cable machine allows you isolate the biceps with this version of the Hammer Curl. This is a good exercise for beginners.","Attach a rope to a cable pulley to the bottom of the weight stack. Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in. Grasp the rope with a close underhand grip (palms facing up). Lower your arms fully to above your thighs and bending only your elbows, raise the rope to your upper chest. Pause for a moment and then return to the starting position.","Note: Keep your elbows at your side throughout this exercise. Do not swing your hips or back during this exercise."],"img":["0216-relaxation.svg","0216-tension.svg"]},{"id":"preacher-curl-with-cable","name":"Cable Preacher Curl","eq":"cable","p":["biceps"],"s":["forearms"],"ins":["Place a padded arm curl bench in front of a cable machine.","Attach a short bar to the bottom pulley.","Rest your arms against the bench and extend them fully.","With a narrow grip (6 inches) grasp the bar with\u00a0palms facing up and pull it towards your head.","Pause for a moment and then lower the bar back to starting position.","Note: Perform this exercise in a slow controlled manner for best results."],"img":["0217-relaxation.svg","0217-tension.svg"]},{"id":"close-grip-ez-bar-curl-with-barbell","name":"Close Grip EZ Bar Curl with Barbell","eq":"barbell","p":["biceps"],"s":["forearms"],"ins":["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp an EZ bar with an underhand close (4 inch) grip on the innermost part of the bar.","Extend your arms fully against your thighs.","Keeping your elbows straight, raise the bar towards your chest.","Pause for moment and then return to the starting position.","Note: Lean up against a wall or post if you have problems keeping from swinging."],"img":["0218-relaxation.svg","0218-tension.svg"]},{"id":"close-grip-standing-biceps-curls-with-barbell","name":"Close Grip Standing Biceps Curls with Barbell","eq":"barbell","p":["biceps"],"s":["forearms"],"ins":["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a barbell with palms up, about 12 inches apart.","Extend your arms fully against your thighs.","Keeping your elbows straight, raise the bar towards your chest until your forearms touch your chest.","Pause for moment and then return to the starting position.","Note: Lean up against a wall or post if you have problems keeping from swinging."],"img":["0219-relaxation.svg","0219-tension.svg"]},{"id":"concentration-curls-with-dumbbell","name":"Concentration Curls with Dumbbell","eq":"dumbbell","p":["biceps"],"s":["forearms"],"ins":["Sit on the end of a flat bench with your feet flat and your legs spread apart.","Grasp a dumbbell in your hand, palms facing up.","With your elbow pressed against your inner thigh, curl the dumbbell up towards your chest.","Slowly return to the starting position.","Repeat and switch arms.","Note:\u00a0Keep all of your body still except the arm you are exercising."],"img":["0220-relaxation.svg","0220-tension.svg"]},{"id":"cross-body-hammer-curl-with-dumbbell","name":"Cross Body Hammer Curl with Dumbbell","eq":"dumbbell","p":["biceps"],"s":["forearms"],"ins":["While standing, grab a dumbbell in each arm with palms facing in.","Keeping your palms facing in (and not twisting your arms) curl the dumbbell up towards your opposite shoulder.","Bring the top of dumbbell up to and touching the shoulder.","Slowly with a controlled manner, lower the dumbbell back to the starting position."],"img":["0221-relaxation.svg","0221-tension.svg"]},{"id":"drag-curl-with-barbell","name":"Drag Curl with Barbell","eq":"barbell","p":["biceps"],"s":["forearms"],"ins":["Stand with your feet shoulder width apart, your knees slightly bent, and your abs drawn in.","Grasp the bar with palms down,\u00a0shoulder width apart.","Extend your arms fully so they are against your thighs.","Slowly raise your arms, palms down, to touch your chest.","Note: Do not move your elbows or shoulders during this exercise."],"img":["0222-relaxation.svg","0222-tension.svg"]},{"id":"alternating-biceps-curl-with-dumbbell","name":"Alternating Bicep Curl with Dumbbell","eq":"dumbbell","p":["biceps"],"s":["forearms"],"ins":["Steps","Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand so your palms are facing up.","Extend your arms so they are at the sides of your body.","Keeping your elbows locked lift your left arm to your chest so that your forearm touches your bicep.","Lower your arm and repeat with your right arm.","Note: Do not swing your body as you perform this exercise."],"img":["0223-relaxation.svg","0223-tension.svg"]},{"id":"biceps-curl-with-dumbbell","name":"Dumbbell Biceps Curl","eq":"dumbbell","p":["biceps"],"s":["forearms"],"ins":["Stand with our feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand with your palms facing up.","Extend your arms so they are at the sides of your body.","Keeping your elbows, locked lift your arms to your chest so that your forearms touch your biceps.","In a slow controlled manner, lower your arms to the starting position.","Note: Do not swing your body as you perform this exercise."],"img":["0224-relaxation.svg","0224-tension.svg"]},{"id":"prone-incline-biceps-curl-with-dumbbell","name":"Prone Incline Biceps Curl with Dumbbell","eq":"dumbbell","p":["biceps"],"s":[],"ins":["Adjust an incline bench to a 45 degree angle.","Grasp dumbbells in each hand and lean face down against the bench, with your feet resting on the floor for support.","Allow your arms to hang down at your sides.","Keeping your elbow straight, raise the dumbbells up towards your head, contracting your biceps.","In a controlled manner, lower the weight and repeat.","Note: Practice steady movements in this exercise, be careful not to let your arms sway."],"img":["0225-relaxation.svg","0225-tension.svg"]},{"id":"ez-bar-curl-with-barbell","name":"EZ Bar Curl with Barbell","eq":"barbell","p":["biceps"],"s":["forearms"],"ins":["Stand with your feet shoulder width apart and your knees slightly bent.","Grasp the barbell with palms up.","Lower the bar so it is against your thighs.","Keeping your elbows still, raise the bar up to your chest so that your forearms touch your biceps.","Note: Lean up against a wall or post to keep yourself from swaying."],"img":["0226-relaxation.svg","0226-tension.svg"]},{"id":"biceps-hammer-curl-with-dumbbell","name":"Dumbbell Hammer Curl","eq":"dumbbell","p":["biceps"],"s":[],"ins":["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand so your palms are facing each other.","Extend your arms so they are at the sides of your body.","Keeping your elbows locked lift your arms in an arc towards your shoulders.","Lower your arms in a steady controlled motion and repeat.","Note: Do not turn your wrists during this exercise."],"img":["0227-relaxation.svg","0227-tension.svg"]},{"id":"flexor-incline-curls-with-dumbbell","name":"Flexor Incline Curls with Dumbbell","eq":"dumbbell","p":["biceps"],"s":[],"ins":["Sit on an incline bench with your feet firmly on the floor in front of you.","Grasp a dumbbell with your palms facing up.","Bring your arms down to your sides and while keeping your wrists as straight as possible, raise your wrists to your shoulders.","Concentrate on squeezing your biceps as you contract (raise) your arms."],"img":["0228-relaxation.svg","0228-tension.svg"]},{"id":"high-cable-curls","name":"High Cable Curls","eq":"cable","p":["biceps"],"s":["triceps"],"ins":["Place a flat bench next to a cable weigh stack.","Attach a short bar to the high pulley.","Lay on your back with your head towards the stack.","Grip the bar with palms facing you)and extend your arms fully on a slight angle over your head.","Pull the bar down towards you, curling your arms as much as possible.","Slowly return to the starting position."],"img":["0229-relaxation.svg","0229-tension.svg"]},{"id":"incline-inner-biceps-curl-with-dumbbell-2","name":"Incline Inner Biceps Curl with Dumbbell","eq":"dumbbell","p":["biceps"],"s":[],"ins":["Adjust an incline bench to a 45 degree angle.","Grasp dumbbells in each hand with and sit down with your back against the bench, with your feet resting on the floor for support.","Allow your arms to hang down at your sides, your palms facing your body.","Keeping your elbow straight, raise the dumbbells up towards your head, contracting your biceps.","In a controlled manner lower the weight and repeat.","Note: Practice steady movements in this exercise, be careful not to let your arms sway."],"img":["0231-relaxation.svg","0231-tension.svg"]},{"id":"lying-bicep-cable-curl","name":"Lying Bicep Cable Curl","eq":"cable","p":["biceps"],"s":["forearms"],"ins":["Attach a short bar to a cable pulley set on the lowest setting.","Lie down on a mat or the floor with your feet touching the weight stack.","Grasp the bar with and palms facing up.","With your arms fully extended and your elbows at your sides, pull the bar in an arc to your chest.","Pause for a moment contracting your biceps, and then return to the starting position."],"img":["0232-relaxation.svg","0232-tension.svg"]},{"id":"lying-close-grip-biceps-curls-with-cable","name":"Lying Close Grip Biceps Curls with Cable","eq":"cable","p":["biceps"],"s":[],"ins":["Place a flat bench under a cable weight stack and attach a flat bar to the pulley.","Lie down with your head towards the stack and your feet firmly on the floor.","Grasp the bar with your\u00a0palms down, about 8 inches apart, and extend your arms straight up.","Curl the bar down in an arc touching your chin.","Slowly return to the starting position."],"img":["0233-relaxation.svg","0233-tension.svg"]},{"id":"lying-high-bench-biceps-curl-with-barbell","name":"Lying High Bench Biceps Curl with Barbell","eq":"barbell","p":["biceps"],"s":[],"ins":["With this exercise your lay face down to isolate your biceps.","Lay face down on a high bench with your head at one end and your toes pressed against the floor to support you.","Grasp a barbell with palms facing up, about 12 inches apart.","Extending your arms to the floor, curl your arms back towards your head in a slight arc, so your biceps touch your forearm.","Slowly return to the starting position."],"img":["0234-relaxation.svg","0234-tension.svg"]},{"id":"lying-supine-biceps-curl-with-dumbbell","name":"Lying Supine Biceps Curl with Dumbbell","eq":"dumbbell","p":["biceps"],"s":[],"ins":["This is another biceps exercise where you lay down to isolate the muscles you are working. This is an advanced exercise.","Lie on a flat bench with your head at one end and your feet planted firmly on the floor.","With a dumbbell in each hand, palms facing in, bring your arms down to your sides, hanging off the bench.","Slowly raise your arms up until they are level with your chest.","Curl the dumbbells by twisting your palms, so that your forearms touch your biceps.","Slowly lower your arms to the starting position.","Note: Practice the motions of this exercise with light weights to become familiar with the movements."],"img":["0235-relaxation.svg","0235-tension.svg"]},{"id":"preacher-curl-with-machine","name":"Machine Preacher Curl","eq":"machine","p":["biceps"],"s":["forearms"],"ins":["A Preacher Curl uses a special bench to support the triceps and isolate the biceps to build the arms. This version of the exercises is a machine exercise. This is a good exercise for beginners.","Adjust the seat of the bench so your arms are level with the top of the bench. Rest your arms against the bench and extend them fully. Grasp the bar underhand (palms facing up) and pull it towards your head. Pause for a moment and then lower the bar back to starting position.","Note:\u00a0Perform this exercise in a slow controlled manner for best results. Read the instructions on the machine before performing this exercise."],"img":["0236-relaxation.svg","0236-tension.svg"]},{"id":"one-arm-preacher-curl-with-dumbbell","name":"One Arm Dumbbell Preacher Curl","eq":"dumbbell","p":["biceps"],"s":["forearms"],"ins":["A Preacher Curl uses a special bench to support the triceps and isolate the biceps to build the arms. This version uses dumbbells and single arm movements for better control.","Adjust the seat of the bench so your arm is level with the top of the bench.","Grasp a dumbbell in your hand with palms facing up.","Rest your arm against the bench and extend it fully down.","Keeping your arm on the bench at all times, curl the dumbbell up towards your head.","Pause for a moment and then lower the dumbbell back to starting position.","Switch arms and repeat.","Note: Perform this exercise in a slow controlled manner for best results."],"img":["0237-relaxation.svg","0237-tension.svg"]},{"id":"overhead-curl-with-cable","name":"Overhead Curl with Cable","eq":"cable","p":["biceps"],"s":[],"ins":["By using cable this exercise isolates and defines the biceps (arm) muscles.","Attach a stirrup handle to each side of a high pulley on a cable machine.","Grasp the handles with palms facing up and stand with your feet shoulder width apart.","Extend your arms fully to each side.","Keeping your elbows steady, curl your wrists towards the sides of your head.","Contract your biceps and pause for a moment.","Then return to the starting position."],"img":["0238-relaxation.svg","0238-tension.svg"]},{"id":"preacher-curl-with-barbell","name":"Barbell Preacher Curl","eq":"barbell","p":["biceps"],"s":["forearms"],"ins":["&nbsp;","Adjust the seat of the bench so that your arms are level with the top of the bench.","Grasp the bar with\u00a0palms facing up, shoulder width apart.","Picking up the bar, rest your arms against the bench and extend them fully.","Keeping your arms on the bench at all times, curl the bar up towards your head.","Pause for a moment and then lower the bar back to starting position.","Note: Perform this exercise in a slow controlled manner for best results."],"img":["0239-relaxation.svg","0239-tension.svg"]},{"id":"preacher-hammer-curl-with-dumbbell","name":"Dumbbell Preacher Curl (Hammer)","eq":"dumbbell","p":["biceps"],"s":[],"ins":["Adjust the seat of the bench so that your arms are level with the top of the bench.","Grasp a dumbbell in each hand with your palms facing each other, shoulder width apart and extend your arms fully along the bench.","Keeping your arms and elbows on the bench at all times, curl the dumbbells up towards your head.","Pause for a moment and then lower the bar back to starting position.","Note:\u00a0Perform this exercise in a slow controlled manner for best results."],"img":["0240-relaxation.svg","0240-tension.svg"]},{"id":"reverse-plate-curls-with-weight","name":"Reverse Plate Curls with Weight","eq":"other","p":["biceps"],"s":["forearms"],"ins":["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a plate in your hands with palms facing down, at the 11:00 and 1:00 o\u2019clock position.","Keeping your elbows and arms at your side, curl the slowly up towards your head.","Slowly return to the starting position."],"img":["0241-relaxation.svg","0241-tension.svg"]},{"id":"seated-close-grip-concentration-curls-with-barbell","name":"Seated Close Grip Concentration Curls with Barbell","eq":"barbell","p":["biceps"],"s":[],"ins":["Concentration exercises limit your range of movement to increase the effectiveness of the movement.\u00a0This version uses a barbell.","Sit on the end of a flat bench with your feet flat and your legs spread apart.","Bend forward at your waist keeping your back straight.","Grasp a barbell in your hands with a close grip approximately 6 inches apart with your palms facing up.","With your elbow pressed against your inner thigh, curl the bar up towards your chest.","Slowly lower the bar to the starting position near the floor.","Note: Keep all of your body still except the arm you are exercising."],"img":["0242-relaxation.svg","0242-tension.svg"]},{"id":"seated-biceps-curl-with-dumbbell","name":"Seated Bicep Curl with Dumbbell","eq":"dumbbell","p":["biceps"],"s":["forearms"],"ins":["Sit on bench with your feet firmly on the floor and your back straight.","Grasp a dumbbell in each hand with your palms facing each other.","Lower the dumbbells to your sides and slowly curl your arms up so your palms are facing up.","Squeeze your biceps at the top and slowly lower to the starting position.","Note: If possible use a short backed bench to help your posture."],"img":["0243-relaxation.svg","0243-tension.svg"]},{"id":"spider-curl-with-barbell","name":"Spider Curl with Barbell","eq":"barbell","p":["biceps"],"s":[],"ins":["Turn a Preacher Curl bench around so you are leaning against the angled side.","Grasp a barbell with palms up, approximately 6 inches apart.","Leaning against the bench, lower the bar along the flat side of the bench fully extending your arms.","Curl your arms up so your biceps are touching your forearms.","Slowly lower the bar to the starting position.","Note: Use a low weight to get used to the motion of this exercise."],"img":["0245-relaxation.svg","0245-tension.svg"]},{"id":"standing-inner-biceps-curl-with-dumbbell","name":"Standing Inner Biceps Curl with Dumbbell","eq":"dumbbell","p":["biceps"],"s":["forearms"],"ins":["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each arm with your palms facing each other, fully extend your arms along your sides.","Curl your arms up and out, turning your palms up and out as you lift.","Slowly lower the dumbbells to the starting position.","Note: Try to keep your forearms in line with your shoulders as you lift the weight."],"img":["0246-relaxation.svg","0246-tension.svg"]},{"id":"standing-one-arm-biceps-curl-with-cable","name":"Standing One Arm Bicep Curl with Cable","eq":"cable","p":["biceps"],"s":["forearms"],"ins":["This is a single arm version of a bicep cable curl. Cable machines are great for helping you learn proper form while building muscle.","Attach a stirrup bar to a low cable pulley.","Stand of the side of the weight stack with your legs shoulder width apart and your knees slightly bent and your abs drawn in.","Grasp the stirrup in one hand with an palms facing up.","Lower the stirrup to the top of your thighs.","Keeping your elbows still, curl the stirrup up towards your chest.","Slowly lower the stirrup to the starting position."],"img":["0247-relaxation.svg","0247-tension.svg"]},{"id":"standing-one-arm-curl-over-incline-bench-with-dumbbell","name":"Standing One Arm Curl Over Incline Bench with Dumbbell","eq":"dumbbell","p":["biceps"],"s":["forearms"],"ins":["Stand in front of an incline bench so your arm is resting on the top of the angled portion of the bench.","Grasp a dumbbell in your hand with palms facing up.","Rest your arm against the back bench and extend it fully down.","Keeping your arm on the bench at all times, curl the dumbbell up towards your head.","Pause for a moment and then lower the dumbbell back to starting position.","Switch arms and repeat.","Note: Perform this exercise in a slow controlled manner for best results."],"img":["0248-relaxation.svg","0248-tension.svg"]},{"id":"two-arm-preacher-curl-with-dumbbell","name":"Dumbbell Preacher Curl (Two Arm)","eq":"dumbbell","p":["biceps"],"s":["forearms"],"ins":["A Preacher Curl uses a special bench to support the triceps and isolate the biceps to build the arms. This version of the exercise uses dumbbells.","Adjust the seat of the bench so your arms are level with the top of the bench.","Grasp a dumbbell in each hand with palms facing up.","Picking up the dumbbells, rest your arms against the bench and extend them fully towards the floor.","Keeping your arms on the bench at all times, curl the weight up towards your head.","Pause for a moment and then lower the weights back to starting position.","Note: Perform this exercise in a slow controlled manner for best results."],"img":["0249-relaxation.svg","0249-tension.svg"]},{"id":"wide-grip-standing-biceps-curl-with-barbell","name":"Wide Grip Standing Biceps Curl with Barbell","eq":"barbell","p":["biceps"],"s":["forearms"],"ins":["This is a wide grip version of a biceps curl. The wider grip targets the lateral or outer portion of the muscle.","Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a barbell with palms up as wide as you comfortably can.","Extend your arms fully against your thighs.","Keeping your elbows straight, raise the bar towards your chest until your forearms touch your chest.","Pause for moment and then return to the starting position.","Note: Lean up against a wall or post if you have problems keeping from swinging."],"img":["0250-relaxation.svg","0250-tension.svg"]},{"id":"zottman-curl-with-dumbbells","name":"Zottman Curl with Dumbbells","eq":"dumbbell","p":["biceps"],"s":["forearms"],"ins":["Stand with your feet shoulder width apart, your knees slightly bent and your and your abs drawn in.","Grasp a dumbbell in each hand with your palms facing each other.","Start with your hands at your sides.","Curl your arms up turning your wrists so they are facing down as the dumbbells reach your chest.","Pause for a moment and then return to the starting position."],"img":["0251-relaxation.svg","0251-tension.svg"]},{"id":"zottman-preacher-curl-with-dumbbells","name":"Dumbbell Preacher Curl (Zottman)","eq":"dumbbell","p":["biceps"],"s":["forearms"],"ins":["Sit at a Preacher Curl Bench.","Grasp a dumbbell in your hand with your palms facing up.","Extend your arm fully along the bench.","Curl your arm up turning your wrist so it faces down as the dumbbell reaches your chest.","Pause for a moment and then return to the starting position and switch arms."],"img":["0252-relaxation.svg","0252-tension.svg"]},{"id":"biceps-curl-with-machine","name":"Machine Biceps Curl","eq":"machine","p":["biceps"],"s":["forearms"],"ins":["Adjust the seat of the machine so your elbows are correctly aligned with the rotation axis.","Press your arms against the pads and keep them stationary throughout the exercise.","Curl your forearms until your arms are fully flexed.","Slowly lower your arms back to the starting position."],"img":["0253-relaxation.svg","0253-tension.svg"]},{"id":"one-arm-biceps-curl-with-olympic-bar-or-barbell","name":"One Arm Bicep Curl with Olympic Bar or Barbell","eq":"barbell","p":["biceps"],"s":["forearms"],"ins":["Stand with your feet shoulder width apart and your knees slightly bent.","Grasp an Olympic bar (empty weight bar) in the middle with one hand so that the bar is equally balanced.","Keep your free hand at your side for support.","Curl the bar up so your forearm touches your bicep.","Slowly lower the bar and change arms.","Note: If an Olympic bar is too heavy use a lighter weight barbell."],"img":["0254-relaxation.svg","0254-tension.svg"]},{"id":"biceps-curl-seated-on-stability-ball-with-dumbbell","name":"seated Stability Ball with Dumbbell Biceps Curl","eq":"dumbbell","p":["biceps"],"s":["forearms"],"ins":["This version of a biceps curl uses a Stability Ball. Exercises preformed with Stability Balls encourage better posture and core muscle development.","Grasp a dumbbell in each hand while sitting\u00a0on a Stability Ball with your feet placed firmly in front of you, and your abs drawn in.","Keeping your elbows at your side and your back straight, curl your arms up to your chest.","Pause for a moment, contracting your biceps.","Slowly lower your arms to the starting position."],"img":["0255-relaxation.svg","0255-tension.svg"]},{"id":"biceps-curl-squat-with-dumbbell","name":"Squat with Dumbbell Biceps Curl","eq":"dumbbell","p":["biceps"],"s":["hamstrings","glutes"],"ins":["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand and curl your arms up to your shoulders.","Bending at the waist, squat down as you lower your hands to the floor (the lower part of a curl).","Pause for a moment and then return to the starting position.","Note: Contract your biceps as you curl your arms up."],"img":["0256-relaxation.svg","0256-tension.svg"]},{"id":"biceps-curl-reverse-with-dumbbells","name":"Dumbbell Biceps Curl (Reverse)","eq":"dumbbell","p":["biceps"],"s":["forearms"],"ins":["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in each hand with palms facing down.","Keeping your arms at your side your elbows steady, lift the dumbbells up towards your shoulders.","Pause for a moment and then return to the starting position."],"img":["0257-relaxation.svg","0257-tension.svg"]},{"id":"one-arm-bicep-concentration-on-stability-ball-with-dumbbell","name":"One Arm Bicep Concentration on Stability Ball with Dumbbell","eq":"dumbbell","p":["biceps"],"s":["forearms"],"ins":["Grasp a dumbbell in one hand and sit on a Stability Ball with your feet wide apart.","Bend forward leaning at the waist.","With the dumbbell in your hand, place your elbow against your knee.","Lower your arm so it is flat against your calves.","Curl your arm up to your chest keeping your elbow steady.","Return to starting position and change hands."],"img":["0258-relaxation.svg","0258-tension.svg"]},{"id":"biceps-curl-with-deadlift-with-barbell","name":"Barbell Dead Lift (Biceps Curl)","eq":"barbell","p":["biceps"],"s":["calves","lower back","hamstrings"],"ins":["This is an advanced exercise. This exercise combines a bicep curl with a deadlift.","Grasp an EZ Curl or barbell with palms facing up.","Standing with your feet shoulder width apart and your knees slightly bent, draw your abs in.","Extend your arms so the bar rests in front of your thighs.","Bending at the waist, bring the bar down to just above the floor.","As you return to a standing position, bring the bar up and curl your arms bringing your forearms to your biceps.","Return the starting position and repeat.","Note: Performing this exercise in front of a mirror may help you spot and correct your form."],"img":["0259-relaxation.svg","0259-tension.svg"]},{"id":"biceps-curl-with-overhead-extension-using-dumbbells-on-stability-ball","name":"Stability Ball with Dumbbell Biceps Curl (Overhead Extension)","eq":"dumbbell","p":["triceps","biceps"],"s":["forearms","shoulders"],"ins":["This is an advanced exercise. This exercise requires you to be able to balance kneeling on a stability ball before you can correctly perform this exercise.","Grasp a dumbbell in each hand with palms facing up.","Kneel on a Stability Ball, drawing your abs in and keeping your back straight.","Raise one arm up over your shoulder and keep your other arm curled.","Bend your raised arm back as if performing a triceps extension while lowering your other arm and curling it back.","Return to starting position and repeat arms.","Note: Work with a Personal Trainer or Instructor to learn how to safely perform this exercise."],"img":["0260-relaxation.svg","0260-tension.svg"]},{"id":"quick-alternating-biceps-curls-with-band","name":"Quick Alternating Biceps Curls with Band","eq":"band","p":["biceps"],"s":["triceps"],"ins":["Place a bungy under your feet and hold the handles palms forward in your hands.","Stand with your feet shoulder width apart, knees slightly bent and your abs drawn in.","Curl your arms up and down in an alternating motion, keeping your body straight.","As you become comfortable with the motion, increase your speed.","Note: Contract your biceps as you curl your arms up."],"img":["0261-relaxation.svg","0261-tension.svg"]},{"id":"biceps-curl-lunge-with-bowling-motion","name":"Medicine Ball Biceps Curl (Lunge, Bowling Motion)","eq":"ball","p":["biceps"],"s":["calves","triceps","hamstrings","glutes","quads"],"ins":["Hold a Medicine Ball in one hand with your palms facing up at shoulder height.","Bring one foot back and into a lunge, keeping your front foot stationary and not letting your back knee touch the ground.","While lunging, bring the ball down and back as if you were bowling.","Bring your arm back up to the starting position, switch legs and repeat.","Note: Use slow and steady movements with this exercies."],"img":["0262-relaxation.svg","0262-tension.svg"]},{"id":"biceps-curl-on-stability-ball-with-leg-raised","name":"Stability Ball with Dumbbell Biceps Curl (leg raised)","eq":"dumbbell","p":["biceps"],"s":["hamstrings","forearms","quads","calves"],"ins":["Grasp a dumbbell in each hand with a palms up grip.","Place the top of one foot behind you on a Stability Ball (see illustration) as if you were stretching your leg.","Keep your back straight and your abs drawn in.","Bring your arms down in front of your legs.","Raise your arms up, curling and contracting your biceps.","Lower your arms and return to starting position and switch legs."],"img":["0263-relaxation.svg","0263-tension.svg"]},{"id":"lateral-lunge-with-biceps-curl-with-dumbbell","name":"Lateral Lunge with Bicep Curl with Dumbbell","eq":"dumbbell","p":["quads","biceps"],"s":["forearms","hamstrings","glutes","calves","abductors"],"ins":["Grasp a dumbbell in each hand with your palms facing up.","Stand with your feet together, your back straight and your abs drawn in.","Allow your arms to extend down fully in front of your thighs.","While keeping your body straight, take a step sideways and then bend your waist and your knee into a lunge.","As you go into the lunge, curl your arms up towards your shoulders contracting your biceps.","Return to starting position and switch legs.","Note: Have a Personal Trainer or Instructor show you how to properly perform this exercise."],"img":["0264-relaxation.svg","0264-tension.svg"]},{"id":"forward-lunge-with-biceps-curl-using-dumbbell","name":"Forward Lunge with Bicep Curl using Dumbbell","eq":"dumbbell","p":["biceps"],"s":["calves","abductors","forearms","hamstrings","glutes"],"ins":["Grasp a dumbbell in each hand with your palms facing up.","Stand with your feet together, your back straight and your abs drawn in.","Allow your arms to extend down fully to the sides of your body.","While keeping your body straight, take a step forward then bend your waist and your knee into a lunge.","Be careful not to let your back knee drop to the floor.","As you go into the lunge, curl your arms up towards your shoulders, contracting your biceps.","Return to starting position and switch legs.","Note: Have a Personal Trainer or Instructor show you how to properly perform this exercise."],"img":["0265-relaxation.svg","0265-tension.svg"]},{"id":"step-up-single-leg-balance-with-biceps-curl-using-dumbbells","name":"Dumbbell Step Up (Bicep Curl, Single Leg Balance)","eq":"dumbbell","p":["biceps"],"s":["abs","quads","forearms","hamstrings","glutes","calves"],"ins":["This is an advanced exercise. This exercise combines a step up with a bicep curl.","Place a box or bench in front of you.","Place a dumbbell in each hand with palms facing up.","Keep your back straight, your shoulders back and your abs drawn in.","With one leg, step up on to the box and raise your other leg up (as if taking another step).","At the top of the step, curl your arms up by bringing your biceps towards your shoulders.","Return to the starting position and switch legs."],"img":["0266-relaxation.svg","0266-tension.svg"]},{"id":"medicine-ball-biceps-curl-on-stability-ball","name":"Medicine Ball Biceps Curl on Stability Ball","eq":"ball","p":["biceps"],"s":["abs","forearms"],"ins":["Sit on a Stability Ball with your feet firmly on the floor in front of you.","Sit with your back straight, your shoulders back and your abs drawn in.","Hold a Medicine Ball in one hand and curl it up bringing your forearm up to your bicep.","Return to starting position and switch arms.","Note: Grasp the Medicine Ball with your fingers spread wide to balance the ball."],"img":["0267-relaxation.svg","0267-tension.svg"]},{"id":"stork-stance-biceps-curl-with-dumbbells","name":"Stork Stance Bicep Curl with Dumbbells","eq":"dumbbell","p":["biceps"],"s":["quads","hamstrings","glutes","calves","triceps"],"ins":["Grasp a pair of dumbbells in each hand, palms facing up.","Standing on one foot, extend your other foot back (see illustration) and extend your arms down so they are handing in front of your leg.","While on one foot, curl your arms up contracting your biceps.","Return to the starting position and switch legs.","Note: Have a Personal Trainer or Instructor show you how to properly perform this exercise."],"img":["0268-relaxation.svg","0268-tension.svg"]},{"id":"biceps-curl-v-sit-on-dome-with-dumbbells","name":"V-Sit on Dome with Dumbbells Biceps Curl","eq":"dumbbell","p":["biceps"],"s":["abs"],"ins":["Grasp a dumbbell in each hand and sit on a dome.","Keep your legs together and your knees bent.","Draw in and hold your abs and keep your back straight.","With you arms extended to your sides, curl and contract your biceps, bringing your forearms towards your shoulders.","Slowly return to the starting position.","Note: Try to keep your balance steady and not move your legs throughout this exercise."],"img":["0269-relaxation.svg","0269-tension.svg"]},{"id":"ankle-circles","name":"Ankle Circles","eq":"bodyweight","p":["calves"],"s":[],"ins":["Stand on one foot near a chair or wall for support.","Lift your foot off the ground and draw circles clockwise in the air with your toes.","Reverse the direction (counter-clockwise) as well as switch feet."],"img":["0270-relaxation.svg","0270-tension.svg"]},{"id":"seated-calf-raise-with-barbell","name":"Seated Calf Raise with Barbell","eq":"barbell","p":["calves"],"s":[],"ins":["Place a block on the floor about one foot in front of a bench.","Sit on the bench with a barbell across your upper thighs and the balls of your feet on the block.","Slowly raise and lower your toes up as high as possible without lifting your foot off the block."],"img":["0272-relaxation.svg","0272-tension.svg"]},{"id":"calves-press-on-leg-machine","name":"Calves Press on Leg Machine","eq":"machine","p":["calves"],"s":[],"ins":["Sit down on a Leg Press Machine and press the plate up as if you were performing a leg press.","Slide your feet down so that the balls of your feet are pressing against the rack (with your heels hanging free).","Keeping the handles locked, press up and flex your toes and then slowly bring your toes back towards your body.","Perform theses movements slowly for maximum benefit.","Note:\u00a0Use a lighter weight on this exercise than you are able to lift with a leg press until you are familiar with the movements."],"img":["0273-relaxation.svg","0273-tension.svg"]},{"id":"calf-raises-with-band","name":"Calf Raises with Band","eq":"band","p":["calves"],"s":[],"ins":["Stand with your toes on an exercise band and raise the handles up to your shoulders.","Raise up on your toes, keeping your hands up by your shoulders.","Pause for a moment and then lower your heel to the floor.","Repeat."],"img":["0274-relaxation.svg","0274-tension.svg"]},{"id":"donkey-calf-raises","name":"Donkey Calf Raises","eq":"bodyweight","p":["calves"],"s":[],"ins":["This is an old school gym exercise which requires the assistance of another person. This is an advanced exercise and not recommended for beginners.","Bend your waist and lean your arms against a weight rack or bench that is waist height.","Have a partner sit on top of your lower back.","Raise up on your toes leaning slightly forward.","Pause at the top and then lower your heels to the floor.","Note: Have a Personal Trainer or Instructor show you how to perform this exercise safely."],"img":["0275-relaxation.svg","0275-tension.svg"]},{"id":"seated-one-leg-calf-raise-with-dumbbell","name":"Seated One Leg Calf Raise with Dumbbell","eq":"dumbbell","p":["calves"],"s":[],"ins":["This version of a calf raise allows you to exercise each leg individually. This exercise is helpful to people who are rehabilitating from injury as it allows you flexibility with the weight.","Place a block on the floor about one foot in front of a bench.","Sit on the bench with a dumbbell across your upper thigh and the balls of one foot on the block.","Slowly raise and lower your toe up as high as possible without lifting your foot off the block.","Switch feet and repeat."],"img":["0276-relaxation.svg","0276-tension.svg"]},{"id":"knee-circles","name":"Knee Circles","eq":"bodyweight","p":["calves"],"s":["hamstrings"],"ins":["Stand with your feet a little closer than shoulder width apart.","Keeping your arms across your chest or on your hips, move your knees in a circular motion, paying attention to keeping your feet flat on the floor and the movement in your ankles.","Note: Do not perform this exercise is you have rolled or unstable ankles."],"img":["0277-relaxation.svg","0277-tension.svg"]},{"id":"rocking-standing-calf-raise-with-barbell","name":"Rocking Standing Calf Raise with Barbell","eq":"barbell","p":["calves"],"s":[],"ins":["Stand with a bar across your shoulders.","With your feet flat on the floor, lift your feet up and forward as if you are performing a calf raise.","Then \u201crock\u201d back onto your ankles so your toes are flexed and off the floor.","Return to starting position.","Note: Wear running or cross training shoes while performing this exercise. Try performing this exercise without weight to become familiar with the movement,"],"img":["0278-relaxation.svg","0278-tension.svg"]},{"id":"seated-calf-raise-using-machine","name":"Seated Calf Raise using Machine","eq":"machine","p":["calves"],"s":[],"ins":["Sit at a calf raise machine.","Put the balls of your feet on the footpad.","Place your thighs under the leg pad above your knees.","Unlock the bar and slowly raise your toes up as far as possible.","Pause for a moment and then return to the starting position.","Note: Practice slow and precise movements with this exercise."],"img":["0279-relaxation.svg","0279-tension.svg"]},{"id":"smith-machine-reverse-calf-raises","name":"Smith Machine Reverse Calf Raises","eq":"smith machine","p":["calves"],"s":[],"ins":["Place a block or low box under the bar at a Smith Machine.","Stand on the edge of the box with your toes hanging off.","Place the bar across your shoulders and lean forward lifting your ankles off the box.","Return to the starting position.","Note: Use the bar for support as you perform this exercise."],"img":["0280-relaxation.svg","0280-tension.svg"]},{"id":"standing-barbell-calf-raise","name":"Standing Barbell Calf Raise","eq":"barbell","p":["calves"],"s":[],"ins":["Place a block or two free weight plates on the floor.","Place a barbell across your back and step up so the balls of your feet are on the block.","Slowly lift your heels up and then lower them back to the floor getting as much of a stretch as possible.","Return to starting position."],"img":["0281-relaxation.svg","0281-tension.svg"]},{"id":"standing-calf-raises-using-machine","name":"Standing Calf Raise (Machine)","eq":"machine","p":["calves"],"s":[],"ins":["Stand with your toes on the footpad of the machine and adjust your shoulders under the upper pads.","Raise up on the balls of your feet, lifting your heels off the pad.","Hold for a moment and then return to the starting position."],"img":["0282-relaxation.svg","0282-tension.svg"]},{"id":"air-bike","name":"Air Bike","eq":"bodyweight","p":["abs"],"s":[],"ins":["Lie on your back on a mat.","Place your hands on either side of your head (over your ears).","Raise your legs up, bending your knees and keeping your calves parallel to the floor.","Bring your left arm elbow up to meet your right knee, as if riding a bike.","Repeat with your right elbow and left knee.","Continue alternating sides.","Note: Move your arms across your chest, squeezing your abs as you move."],"img":["0284-relaxation.svg","0284-tension.svg"]},{"id":"ab-rollout-with-barbell","name":"Ab Rollout with Barbell","eq":"barbell","p":["abs"],"s":["lower back","shoulders"],"ins":["Place a barbell on the floor at your feet.","Bending at the waist, grip the barbell with a shoulder with overhand grip.","With a slow controlled motion, roll the bar out so that your back is straight.","Keep your arms straight throughout the exercise.","Roll back up raising your hips and butt as you return to the starting position.","Note: Practice raising your hips and butt as high as you can with this exercise."],"img":["0285-relaxation.svg","0285-tension.svg"]},{"id":"ab-rollout-on-knees-with-barbell","name":"Ab Rollout on Knees with Barbell","eq":"barbell","p":["abs"],"s":["lower back","shoulders"],"ins":["Place a barbell on the floor in front of you.","Start by kneeling in front of the bar, grip the barbell with a shoulder with overhand grip.","With a slow controlled motion, roll the bar out so that your back is straight, bend your knees and keep your feet off the floor.","Keep your arms straight throughout the exercise.","Roll back up bring the bar under your shoulders and return to the starting position."],"img":["0286-relaxation.svg","0286-tension.svg"]},{"id":"bent-knee-hip-raise","name":"Bent Knee Hip Raise","eq":"bodyweight","p":["abs"],"s":[],"ins":["Lie on your back with your arms outstretched to your sides.","Bend your knees at a 60 degree angle and hold your feet up just off the floor.","Keeping your back and arms down, raise your hips up and off the floor so that your knees are over your chest.","Contract your abs for a moment and then return to the starting position."],"img":["0287-relaxation.svg","0287-tension.svg"]},{"id":"seated-ab-crunch-with-cable","name":"Seated Ab Crunch with Cable","eq":"cable","p":["abs"],"s":[],"ins":["Attach a rope to a high cable pulley.","Place a bench in front of cable weight stack.","Grasp the rope over your shoulders and sit with your back towards the stack.","With your feet firmly on the floor and keeping your hips steady, flex at the waist bringing your elbows towards your knees.","Return to the starting position.","Note: Perform this exercise in a slow controlled manner."],"img":["0288-relaxation.svg","0288-tension.svg"]},{"id":"cross-body-crunch","name":"Cross Body Crunch","eq":"bodyweight","p":["abs"],"s":[],"ins":["Lie on your back and bring your knees up to a 60 degree angle, keep your feet flat on the floor.","Place your hands on either side of your head (over your ears).","Curl up raising your right elbow and your left knee so that they touch over your chest.","Return to the starting position and repeat with alternate arms and legs.","Note: Contract your abs as you twist during this exercise."],"img":["0289-relaxation.svg","0289-tension.svg"]},{"id":"crunches-with-legs-on-stability-ball","name":"Crunches with Legs on Stability Ball","eq":"ball","p":["abs"],"s":[],"ins":["Lie on your back and place your feet up on a stability ball.","Place your hands across your chest, or on either side of your head.","Keeping the small of your back on the floor, raise your head, shoulders and chest up and off the floor.","Pause for a moment contracting your abs and then return to the starting position.","Note:\u00a0Take your time and perform this exercise in a slow controlled manner."],"img":["0290-relaxation.svg","0290-tension.svg"]},{"id":"crunches","name":"Crunch","eq":"bodyweight","p":["abs"],"s":[],"ins":["This is the most common abdominal exercise and possibly the most often improperly performed. Here is how to perform it correctly.","Lie on your back with your feet up on a bench and your knees bent at a 90 degree angle.","Place your hands across your chest or on either side of your head (over your ears).","Raise your head, shoulders and chest off the floor and towards your knees, crunching your abs.","Hold the position for a moment and then lower to the starting position.","Note: Keep your hips straight and your lower back against the floor during this exercise."],"img":["0291-relaxation.svg","0291-tension.svg"]},{"id":"decline-crunch","name":"Decline Crunch","eq":"bodyweight","p":["abs"],"s":[],"ins":["Lie on a decline bench face up.","Place your feet securely under the pads.","Place your hands either across your chest or on either side of your head (over your ears).","Lay fully back and then rise slowly crunching your abs.","Pause for a moment and then return to the starting position.","Note:\u00a0Use the full range of movement in this exercise for the optimal results."],"img":["0292-relaxation.svg","0292-tension.svg"]},{"id":"decline-oblique-crunch","name":"Decline Oblique Crunch","eq":"bodyweight","p":["abs"],"s":[],"ins":["This version of a decline crunch isolates the oblique (side) muscles of the abs.","Lie on a decline bench face up.","Place your feet securely under the pads.","Place your hands either across your chest or on either side of your head (over your ears).","Raise your shoulders and chest up keeping your back straight and bring your left elbow to your right knee, slowly crunching your abs.","Pause for a moment and then return to the starting position.","Lay fully back and repeat with your right elbow to your left knee."],"img":["0293-relaxation.svg","0293-tension.svg"]},{"id":"side-bend-with-dumbbell","name":"Side Bend with Dumbbell","eq":"dumbbell","p":["abs"],"s":[],"ins":["Stand with your feet shoulder width apart, your knees slightly bent and your abs drawn in.","Grasp a dumbbell in one hand and standing straight upright, bend at the waist as far as possible to one side.","Slowly return back up to the staring position.","Switch the dumbbell to your other hand and repeat the exercise.","Note: Be careful to bend only at your waist and not at the hips or knees."],"img":["0294-relaxation.svg","0294-tension.svg"]},{"id":"stability-ball-abdominal-crunch","name":"Stability Ball Abdominal Crunch","eq":"bodyweight","p":["abs"],"s":[],"ins":["This crunch uses a Stability Ball. The ball allows you a better range of movement because it adapts better to your spine.","Sit on top of an exercise or stability ball with your feet placed firmly on the floor for support.","Position yourself so that your lower back is centered on the middle of the ball.","Lie back and bring your hands across your chest, or on either side of your head (over your ears).","Raise your head, chest and shoulders up crunching your abs as you sit upright.","Pause for a moment and then lower yourself to the starting position.","Note: For best results, use a full range of motion in this exercise."],"img":["0295-relaxation.svg","0295-tension.svg"]},{"id":"exercise-ball-pull-in","name":"Exercise Ball Pull In","eq":"bodyweight","p":["abs"],"s":[],"ins":["Lay down as if you were performing a pushup.","Place your feet and shins over an exercise or stability ball.","Keeping your back straight and supporting your weight on your hands, pull your knees towards your chest, so the ball rolls forward under your ankles.","Crunch your abs and then roll the ball back to starting position straighten your legs.","Note: Keep your back straight as you perform this exercise."],"img":["0296-relaxation.svg","0296-tension.svg"]}];
